1	#!/usr/bin/env node
2	"use strict";
3	/**
4	 * Nxeon node-agent — see docs/DOCUMENTATION.md's "Multi-node synergy" section
5	 * for the full design. Runs on every NON-PRIMARY compute node. Gives the
6	 * primary's worker a narrow, token-authenticated way to touch this node's own
7	 * NAT table and cloud-init snippet storage — the two host-level operations
8	 * the worker cannot reach any other way once it isn't running on this box.
9	 *
10	 * DELIBERATELY plain, dependency-free JavaScript (Node built-ins only: http,
11	 * https, fs, child_process, crypto, url) — this ONE file is copied to a
12	 * freshly onboarded node that has no npm packages, no copy of this repo, and
13	 * should need neither. No database access, no Proxmox API token, nothing
14	 * beyond what these operations need — a leaked token's blast radius is NAT
15	 * rules and cloud-init snippets for this one node, never a shell, never data.
16	 *
17	 * AUTH: every request must carry `Authorization: Bearer <token>`, checked by
18	 * constant-time comparison against NXEON_AGENT_TOKEN (env, sourced from
19	 * /etc/nxeon/node-agent.env — the only copy of the plaintext token on this
20	 * machine; the primary's copy is encrypted at rest, see lib/node-agent.ts).
21	 * Network exposure is ADDITIONALLY restricted by this node's own firewall to
22	 * the primary's public IP only (see onboard-node.sh's agent-allow rule) — the
23	 * token is defense in depth on top of that, not the only gate.
24	 *
25	 * TRANSPORT: HTTPS with a self-signed cert generated once at onboard time
26	 * (openssl, no CA involved). The primary connects with certificate
27	 * verification disabled — the SAME trust model this codebase already uses to
28	 * reach this node's own Proxmox API (lib/proxmox.ts's insecureAgent) — which
29	 * still encrypts the token on the wire without needing a CA-issued cert for a
30	 * bare IP with no public DNS name.
31	 *
32	 * Run directly: node node-agent/index.js
33	 * As a service: deploy/nxeon-node-agent.service (installed by onboard-node.sh)
34	 */
35	
36	const https = require("node:https");
37	const fs = require("node:fs");
38	const path = require("node:path");
39	const crypto = require("node:crypto");
40	const { execFile, spawn } = require("node:child_process");
41	const { pipeline } = require("node:stream/promises");
42	
43	const PORT = Number(process.env.NXEON_AGENT_PORT || 8943);
44	const TOKEN = process.env.NXEON_AGENT_TOKEN || "";
45	const TLS_KEY = process.env.NXEON_AGENT_TLS_KEY || "/etc/nxeon/node-agent.key.pem";
46	const TLS_CERT = process.env.NXEON_AGENT_TLS_CERT || "/etc/nxeon/node-agent.cert.pem";
47	// Generous enough for any real cloud-init snippet (a few KB of YAML/bash);
48	// bounded so a malformed/malicious body can't exhaust memory.
49	const MAX_BODY_BYTES = 1024 * 1024;
50	const CMD_TIMEOUT_MS = 15_000;
51	
52	if (!TOKEN || TOKEN.length < 20) {
53	  console.error("[node-agent] NXEON_AGENT_TOKEN is missing or suspiciously short — refusing to start. " +
54	    "onboard-node.sh generates a proper one; don't hand-edit /etc/nxeon/node-agent.env with a short value.");
55	  process.exit(1);
56	}
57	if (!Number.isInteger(PORT) || PORT < 1 || PORT > 65535) {
58	  console.error(`[node-agent] NXEON_AGENT_PORT=${process.env.NXEON_AGENT_PORT} is not a valid port — refusing to start.`);
59	  process.exit(1);
60	}
61	
62	// ---- Validation — mirrors lib/nat-rules.ts's own rules; keep in sync ------
63	const IPV4_RE = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
64	const CHAIN_RE = /^[A-Z0-9_]{1,40}$/;
65	const STORAGE_RE = /^[a-zA-Z0-9_-]{1,60}$/;
66	// Matches exactly the filenames worker/index.ts's provision() ever asks for:
67	// nxeon-<vmid>.yaml. Nothing else is ever written or deleted by this agent.
68	const FILENAME_RE = /^nxeon-\d+\.yaml$/;
69	// Root of this node's own local disaster-recovery backups (see
70	// scripts/backup-vms.sh / backup-pve-config.sh, which write here directly —
71	// this agent never writes into it, only reads). Matches those scripts'
72	// own NXEON_PLATFORM_BACKUP_DIR/NXEON_BACKUP_STATUS_DIR defaults
73	// (/tank/backup/platform, /tank/backup/status), one level up.
74	const BACKUP_ROOT = process.env.NXEON_AGENT_BACKUP_ROOT || "/tank/backup";
75	// Allowlist of relative paths this agent will ever list or stream — exactly
76	// the filenames backup-pve-config.sh / backup-vms.sh produce. Read-only:
77	// there is no write/delete counterpart, unlike the snippet endpoints above —
78	// the primary only ever pulls from here, never pushes.
79	const BACKUP_REL_RE =
80	  /^(platform\/(host-config-\d{8}-\d{6}\.tar\.gz|vzdump-qemu-\d+-\d{4}_\d{2}_\d{2}-\d{2}_\d{2}_\d{2}\.(vma\.zst|log)|vm-names\.txt)|hypervisor\/hypervisor-[A-Za-z0-9.-]+-\d{8}-\d{6}\.tar\.gz|status\/(host-config|vm-backup|hypervisor|backup-run)\.json)$/;
81	
82	/** True only for an actual string matching `re` — RegExp#test() coerces its
83	 *  argument, so `CHAIN_RE.test(123)` would otherwise pass (stringifies to
84	 *  "123", which matches [A-Z0-9_]) and hand a NUMBER to execFile's argv array
85	 *  a few lines later. Every JSON-body-derived field is checked with this,
86	 *  never a bare `.test()`, so a type-confused value is rejected up front
87	 *  instead of surfacing as a confusing execFile error downstream. */
88	function isStr(v, re) {
89	  return typeof v === "string" && re.test(v);
90	}
91	
92	function isValidPort(n) {
93	  return Number.isInteger(n) && n >= 1 && n <= 65535;
94	}
95	function isValidRule(r) {
96	  return (
97	    !!r &&
98	    (r.proto === "tcp" || r.proto === "udp") &&
99	    isValidPort(r.dport) &&
100	    typeof r.destIp === "string" &&
101	    IPV4_RE.test(r.destIp) &&
102	    isValidPort(r.destPort)
103	  );
104	}
105	/** Argv fragment shared by -A/-D — mirrors lib/nat-rules.ts's ruleSpec(). */
106	function ruleSpec(r) {
107	  return ["-p", r.proto, "--dport", String(r.dport), "-j", "DNAT", "--to-destination", `${r.destIp}:${r.destPort}`];
108	}
109	
110	// ---- constant-time bearer check --------------------------------------------
111	function checkAuth(req) {
112	  const header = req.headers["authorization"] || "";
113	  const m = /^Bearer (.+)$/.exec(header);
114	  if (!m) return false;
115	  const presented = Buffer.from(m[1]);
116	  const expected = Buffer.from(TOKEN);
117	  // timingSafeEqual throws on a length mismatch rather than returning false —
118	  // guard it explicitly so a short/garbled header can't produce a stack trace.
119	  if (presented.length !== expected.length) return false;
120	  return crypto.timingSafeEqual(presented, expected);
121	}
122	
123	// ---- ZFS (VM move transport) — argv arrays only, NEVER a shell string -------
124	//
125	// Added 2026-10-01 for lib/vm-move (worker/vm-move.ts): the primary's worker
126	// streams a VM disk's `zfs send` into this node (`POST /v1/zfs/recv`) or pulls
127	// one out of it (`GET /v1/zfs/send`) when this node is the SOURCE of a move
128	// between two non-primary nodes. Every dataset name must be a Proxmox VM disk
129	// (`<pool>/vm-<vmid>-disk-<n>`) under an allowlisted pool path, every
130	// snapshot name must be one this engine itself creates (`nxmove1-<id>` /
131	// `nxmove2-<id>`), and the destructive endpoint refuses to touch a dataset
132	// whose vmid still has a VM config on this node. Mirrors lib/vm-move/plan.ts's
133	// ZFS_POOL_RE / VM_DISK_RE / MOVE_SNAPSHOT_RE — keep in sync.
134	const ZFS_POOL_RE = /^[a-z][a-z0-9_-]{0,31}(\/[a-z][a-z0-9_-]{0,31}){0,3}$/;
135	const VM_DISK_RE = /^vm-(\d{3,9})-disk-(\d{1,2})$/;
136	const MOVE_SNAPSHOT_RE = /^nxmove[12]-[a-z0-9]{10,40}$/;
137	// zfs receive_resume_token: opaque base64-ish blob; kept shell-inert (argv only anyway).
138	const RESUME_TOKEN_RE = /^[A-Za-z0-9+/=_-]{16,4096}$/;
139	const ZFS_CMD_TIMEOUT_MS = 60_000;
140	
141	/** `<pool>/vm-N-disk-M` → { pool, vmid } or null. */
142	function parseVmDataset(dataset) {
143	  if (typeof dataset !== "string" || dataset.length > 160) return null;
144	  const slash = dataset.lastIndexOf("/");
145	  if (slash <= 0) return null;
146	  const pool = dataset.slice(0, slash);
147	  const name = dataset.slice(slash + 1);
148	  if (!ZFS_POOL_RE.test(pool)) return null;
149	  const m = VM_DISK_RE.exec(name);
150	  if (!m) return null;
151	  return { pool, vmid: Number(m[1]) };
152	}
153	
154	function zfs(args) {
155	  return new Promise((resolve, reject) => {
156	    execFile("zfs", args, { timeout: ZFS_CMD_TIMEOUT_MS, maxBuffer: 4 * 1024 * 1024 }, (err, stdout, stderr) => {
157	      if (err) return reject(new Error(String(stderr || err.message).trim().slice(0, 400)));
158	      resolve(stdout);
159	    });
160	  });
161	}
162	
163	function vmConfigExists(vmid) {
164	  return fs.existsSync(`/etc/pve/qemu-server/${vmid}.conf`);
165	}
166	
167	/** GET /v1/zfs/dataset?dataset=… → existence, sizes and this engine's snapshots. */
168	async function handleZfsDataset(_req, res, dataset) {
169	  if (!parseVmDataset(dataset)) return sendJson(res, 400, { error: "invalid dataset" });
170	  let line;
171	  try {
172	    line = await zfs(["list", "-Hp", "-o", "used,referenced,volsize", dataset]);
173	  } catch (e) {
174	    if (/does not exist/.test(e.message)) return sendJson(res, 200, { exists: false });
175	    throw e;
176	  }
177	  const [used, referenced, volsize] = line.trim().split(/\s+/).map(Number);
178	  const snapshots = await listSnapshots(dataset);
179	  const tokenRaw = await zfs(["get", "-H", "-o", "value", "receive_resume_token", dataset]).catch(() => "-");
180	  const tok = tokenRaw.trim();
181	  const resumeToken = tok && tok !== "-" && RESUME_TOKEN_RE.test(tok) ? tok : null;
182	  sendJson(res, 200, { exists: true, usedBytes: used, referencedBytes: referenced, volsizeBytes: volsize, snapshots, resumeToken });
183	}
184	
185	async function listSnapshots(dataset) {
186	  const snapsRaw = await zfs(["list", "-Hp", "-t", "snapshot", "-o", "name", "-d", "1", dataset]).catch(() => "");
187	  return snapsRaw
188	    .split("\n")
189	    .map((s) => s.trim())
190	    .filter(Boolean)
191	    .map((s) => s.slice(s.indexOf("@") + 1));
192	}
193	
194	/** GET /v1/zfs/vm-config?vmid=N → does /etc/pve/qemu-server/N.conf exist here? */
195	async function handleVmConfigExists(_req, res, vmidRaw) {
196	  const vmid = Number(vmidRaw);
197	  if (!Number.isInteger(vmid) || vmid < 100 || vmid > 999999999) return sendJson(res, 400, { error: "invalid vmid" });
198	  sendJson(res, 200, { exists: vmConfigExists(vmid) });
199	}
200	
201	/** POST /v1/zfs/snapshot {dataset, snap} — crash-consistent zfs snapshot (the
202	 *  consistent, guest-agent-frozen one is taken through the Proxmox API by the
203	 *  worker; this is only for the quiescent, stopped-VM incremental pass). */
204	async function handleZfsSnapshot(_req, res, rawBody) {
205	  const p = parseJson(rawBody);
206	  if (!p || !parseVmDataset(p.dataset) || !isStr(p.snap, MOVE_SNAPSHOT_RE)) return sendJson(res, 400, { error: "invalid dataset/snapshot" });
207	  await zfs(["snapshot", `${p.dataset}@${p.snap}`]);
208	  sendJson(res, 200, { ok: true });
209	}
210	
211	/** DELETE /v1/zfs/snapshot {dataset, snap} — only this engine's own snapshots. */
212	async function handleZfsDeleteSnapshot(_req, res, rawBody) {
213	  const p = parseJson(rawBody);
214	  if (!p || !parseVmDataset(p.dataset) || !isStr(p.snap, MOVE_SNAPSHOT_RE)) return sendJson(res, 400, { error: "invalid dataset/snapshot" });
215	  try {
216	    await zfs(["destroy", `${p.dataset}@${p.snap}`]);
217	  } catch (e) {
218	    if (!/does not exist/.test(e.message)) throw e;
219	  }
220	  sendJson(res, 200, { ok: true });
221	}
222	
223	/** DELETE /v1/zfs/dataset {dataset} — rollback of a half-received disk. Refused
224	 *  outright when a VM config for that vmid exists on this node: a disk that
225	 *  belongs to a configured VM is destroyed through Proxmox (qm destroy), by the
226	 *  worker, via the API — never by this agent. */
227	async function handleZfsDestroyDataset(_req, res, rawBody) {
228	  const p = parseJson(rawBody);
229	  const parsed = p && parseVmDataset(p.dataset);
230	  if (!parsed) return sendJson(res, 400, { error: "invalid dataset" });
231	  if (vmConfigExists(parsed.vmid)) return sendJson(res, 409, { error: `vm ${parsed.vmid} has a config on this node — destroy it through Proxmox, not here` });
232	  // Only a dataset THIS engine received may go: every snapshot on it must be
233	  // an nxmove* one (a received move dataset carries only those, or none while
234	  // partial). Anything with a Proxmox/backup snapshot belongs to somebody.
235	  let snapshots = [];
236	  try {
237	    snapshots = await listSnapshots(p.dataset);
238	  } catch (e) {
239	    if (/does not exist/.test(e.message)) return sendJson(res, 200, { ok: true, absent: true });
240	    throw e;
241	  }
242	  const foreign = snapshots.filter((n) => !MOVE_SNAPSHOT_RE.test(n));
243	  if (foreign.length) return sendJson(res, 409, { error: `dataset carries snapshot(s) this engine did not create: ${foreign.slice(0, 3).join(", ")}` });
244	  try {
245	    await zfs(["destroy", "-r", p.dataset]);
246	  } catch (e) {
247	    if (!/does not exist/.test(e.message)) throw e;
248	  }
249	  sendJson(res, 200, { ok: true });
250	}
251	
252	/**
253	 * POST /v1/zfs/recv?dataset=… — body is a zstd-compressed `zfs send` stream.
254	 * Decompressed and received with `-F` (so an incremental lands on the full
255	 * pass's snapshot) and `-u` (never try to mount anything). Refuses a dataset
256	 * whose vmid already has a VM config here (that would be someone's live
257	 * disk), and refuses to create a dataset whose pool path doesn't exist.
258	 */
259	async function handleZfsRecv(req, res, dataset) {
260	  const parsed = parseVmDataset(dataset);
261	  if (!parsed) return sendJson(res, 400, { error: "invalid dataset" });
262	  if (vmConfigExists(parsed.vmid)) return sendJson(res, 409, { error: `vm ${parsed.vmid} already has a config on this node` });
263	  try {
264	    await zfs(["list", "-H", "-o", "name", parsed.pool]);
265	  } catch {
266	    return sendJson(res, 400, { error: `pool ${parsed.pool} does not exist on this node` });
267	  }
268	  const zstd = spawn("zstd", ["-d", "-q", "-T0"], { stdio: ["pipe", "pipe", "pipe"] });
269	  // -s keeps a receive_resume_token on an interrupted stream so the primary can
270	  // continue instead of re-sending the whole disk (GET /v1/zfs/dataset reports it).
271	  const recv = spawn("zfs", ["receive", "-s", "-F", "-u", dataset], { stdio: ["pipe", "pipe", "pipe"] });
272	  let recvErr = "";
273	  recv.stderr.on("data", (d) => (recvErr += d.toString().slice(0, 1000)));
274	  let zstdErr = "";
275	  zstd.stderr.on("data", (d) => (zstdErr += d.toString().slice(0, 1000)));
276	  const recvDone = new Promise((resolve, reject) => {
277	    recv.on("error", reject);
278	    recv.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`zfs receive exited ${code}: ${recvErr.trim()}`))));
279	  });
280	  try {
281	    zstd.stdout.pipe(recv.stdin);
282	    await pipeline(req, zstd.stdin);
283	    await recvDone;
284	  } catch (e) {
285	    try { zstd.kill("SIGKILL"); } catch { /* already gone */ }
286	    try { recv.kill("SIGKILL"); } catch { /* already gone */ }
287	    throw new Error(`${e.message}${zstdErr ? ` (zstd: ${zstdErr.trim()})` : ""}`);
288	  }
289	  sendJson(res, 200, { ok: true });
290	}
291	
292	/**
293	 * GET /v1/zfs/send?dataset=…&snap=…[&from=…] — streams a zstd-compressed
294	 * `zfs send` of `dataset@snap` (incremental from `@from` when given). Used
295	 * when THIS node is the source of a move; the primary pipes it straight into
296	 * the target's recv endpoint.
297	 */
298	async function handleZfsSend(_req, res, dataset, snap, from, token) {
299	  if (!parseVmDataset(dataset)) return sendJson(res, 400, { error: "invalid dataset" });
300	  if (!isStr(snap, MOVE_SNAPSHOT_RE) || (from !== null && !isStr(from, MOVE_SNAPSHOT_RE))) return sendJson(res, 400, { error: "invalid snapshot" });
301	  if (token !== null && !isStr(token, RESUME_TOKEN_RE)) return sendJson(res, 400, { error: "invalid resume token" });
302	  // `zfs send -t <token>` resumes an interrupted receive on the OTHER side; the
303	  // token encodes dataset/snapshot/offset, so -L/-e/-i are not repeated.
304	  const args = token ? ["send", "-t", token] : ["send", "-L", "-e"];
305	  if (!token && from) args.push("-i", `${dataset}@${from}`);
306	  if (!token) args.push(`${dataset}@${snap}`);
307	  const send = spawn("zfs", args, { stdio: ["ignore", "pipe", "pipe"] });
308	  const zstd = spawn("zstd", ["-3", "-q", "-T1"], { stdio: ["pipe", "pipe", "pipe"] });
309	  let sendErr = "";
310	  send.stderr.on("data", (d) => (sendErr += d.toString().slice(0, 1000)));
311	  send.on("close", (code) => {
312	    if (code !== 0) {
313	      console.error(`[node-agent] zfs send ${dataset}@${snap} exited ${code}: ${sendErr.trim()}`);
314	      // Truncate the response so the receiver's zstd/zfs receive fails loudly
315	      // instead of accepting a short stream as complete.
316	      try { zstd.kill("SIGKILL"); } catch { /* gone */ }
317	      res.destroy();
318	    }
319	  });
320	  res.writeHead(200, { "Content-Type": "application/octet-stream" });
321	  send.stdout.pipe(zstd.stdin);
322	  zstd.stdout.pipe(res);
323	  res.on("close", () => {
324	    try { send.kill("SIGKILL"); } catch { /* gone */ }
325	    try { zstd.kill("SIGKILL"); } catch { /* gone */ }
326	  });
327	}
328	
329	// ---- iptables exec — argv arrays only, NEVER a shell string ----------------
330	function iptables(args) {
331	  return new Promise((resolve, reject) => {
332	    execFile("iptables", args, { timeout: CMD_TIMEOUT_MS }, (err, stdout, stderr) => {
333	      if (err) return reject(new Error(String(stderr || err.message).trim().slice(0, 400)));
334	      resolve(stdout);
335	    });
336	  });
337	}
338	
339	async function ensureChain(chain) {
340	  try {
341	    await iptables(["-t", "nat", "-N", chain]);
342	  } catch {
343	    /* chain already exists */
344	  }
345	  try {
346	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", chain]);
347	  } catch {
348	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", chain]);
349	  }
350	}
351	
352	function pvesmPath(storageRef) {
353	  return new Promise((resolve, reject) => {
354	    execFile("pvesm", ["path", storageRef], { timeout: 10_000 }, (err, stdout) => {
355	      if (err) return reject(new Error(`pvesm path ${storageRef}: ${err.message}`));
356	      resolve(stdout.trim());
357	    });
358	  });
359	}
360	
361	// ---- request body helpers ---------------------------------------------------
362	function readBody(req) {
363	  return new Promise((resolve, reject) => {
364	    let size = 0;
365	    const chunks = [];
366	    req.on("data", (c) => {
367	      size += c.length;
368	      if (size > MAX_BODY_BYTES) {
369	        reject(new Error("request body too large"));
370	        req.destroy();
371	        return;
372	      }
373	      chunks.push(c);
374	    });
375	    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
376	    req.on("error", reject);
377	  });
378	}
379	
380	/** Parse a JSON body, or return undefined (never throws) so handlers can 400 cleanly. */
381	function parseJson(text) {
382	  try {
383	    return JSON.parse(text || "{}");
384	  } catch {
385	    return undefined;
386	  }
387	}
388	
389	function sendJson(res, status, obj) {
390	  const body = JSON.stringify(obj);
391	  res.writeHead(status, { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) });
392	  res.end(body);
393	}
394	
395	// ---- route handlers ---------------------------------------------------------
396	
397	async function handleHealth(_req, res) {
398	  // version 3: resumable zfs receive (-s / receive_resume_token / send -t), the
399	  // dataset destroy guard (no foreign snapshots) and /v1/zfs/vm-config.
400	  // version 4: GET /v1/net/neigh (read-only ARP/neighbour table for IPAM).
401	  sendJson(res, 200, { ok: true, version: 4, features: ["zfs", "zfs-resume", "zfs-destroy-guard", "vm-config", "net-neigh"] });
402	}
403	
404	/** GET /v1/net/neigh — the node's IPv4 neighbour (ARP) table, read-only. Used by
405	 *  IPAM so a private address that something on the NAT bridge is ANSWERING for
406	 *  (an orphan VM, a duplicate) is never handed to a new server — 2026-10-02:
407	 *  VM 644 on node-2 was given 10.20.1.101 while VM 101 held it. Fixed argv. */
408	async function handleNeigh(_req, res) {
409	  execFile("ip", ["-4", "-j", "neigh", "show"], { timeout: CMD_TIMEOUT_MS, maxBuffer: 4 * 1024 * 1024 }, (err, stdout, stderr) => {
410	    if (err) return sendJson(res, 500, { error: String(stderr || err.message).slice(0, 300) });
411	    let rows = [];
412	    try { rows = JSON.parse(stdout || "[]"); } catch { return sendJson(res, 500, { error: "unparseable ip -j neigh output" }); }
413	    const out = (Array.isArray(rows) ? rows : []).map((r) => ({
414	      ip: String(r.dst || ""),
415	      mac: r.lladdr ? String(r.lladdr).toLowerCase() : null,
416	      dev: r.dev ? String(r.dev) : null,
417	      state: Array.isArray(r.state) ? r.state.join(",") : String(r.state || ""),
418	    }));
419	    sendJson(res, 200, { neighbors: out });
420	  });
421	}
422	
423	async function handleEnsureChain(_req, res, rawBody) {
424	  const parsed = parseJson(rawBody);
425	  const chain = parsed && parsed.chain;
426	  if (!parsed || !CHAIN_RE.test(chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
427	  await ensureChain(chain);
428	  sendJson(res, 200, { ok: true });
429	}
430	
431	async function handleListChain(_req, res, chain) {
432	  if (!CHAIN_RE.test(chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
433	  // Deliberately NOT swallowed on failure — reconcileNatChain always calls
434	  // ensure-chain immediately before this, so a real failure here (not "chain
435	  // missing", which can't happen given that ordering) is a genuine problem
436	  // the caller needs to see, exactly like the local iptablesHost() in
437	  // worker/network.ts never special-cases this either.
438	  const output = await iptables(["-t", "nat", "-S", chain]);
439	  sendJson(res, 200, { output });
440	}
