442	async function handleAddRule(_req, res, rawBody) {
443	  const parsed = parseJson(rawBody);
444	  if (!parsed || !CHAIN_RE.test(parsed.chain || "")) return sendJson(res, 400, { error: "invalid chain name" });
445	  if (!isValidRule(parsed.rule)) return sendJson(res, 400, { error: "invalid rule" });
446	  await iptables(["-t", "nat", "-A", parsed.chain, ...ruleSpec(parsed.rule)]);
447	  sendJson(res, 200, { ok: true });
