458	/** Resolve `<storage>:snippets/<filename>` via pvesm and refuse anything that
459	 *  didn't land in a real snippets directory — defense in depth beyond the
460	 *  filename/storage allowlists above. */
461	async function resolveSnippetPath(storage, filename) {
462	  const target = await pvesmPath(`${storage}:snippets/${filename}`);
463	  if (!target.includes(`${path.sep}snippets${path.sep}`) && !target.endsWith(`${path.sep}snippets`)) {
464	    throw new Error("storage did not resolve to a snippets path");
465	  }
466	  return target;
467	}
