469	async function handleWriteSnippet(_req, res, rawBody) {
470	  const parsed = parseJson(rawBody);
471	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
472	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
473	  if (typeof parsed.content !== "string" || parsed.content.length > MAX_BODY_BYTES) {
474	    return sendJson(res, 400, { error: "invalid content" });
475	  }
476	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
477	  fs.mkdirSync(path.dirname(target), { recursive: true });
478	  fs.writeFileSync(target, parsed.content, { mode: 0o600 });
479	  sendJson(res, 200, { ok: true });
480	}
