482	async function handleDeleteSnippet(_req, res, rawBody) {
483	  const parsed = parseJson(rawBody);
484	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
485	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
486	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
487	  fs.rmSync(target, { force: true });
