491	async function handleDnatCheck(_req, res, address) {
492	  if (!IPV4_RE.test(address || "")) return sendJson(res, 400, { error: "invalid address" });
493	  const output = await iptables(["-t", "nat", "-S", "PREROUTING"]);
494	  const hasLiveDnatRule = output.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
