498	/** Recursively-flat listing of the two backup subdirs this agent exposes —
499	 *  each entry's `path` is exactly what handleBackupFile expects back. Missing
500	 *  subdirs (e.g. a node with no vzdump guests yet) are not an error — an
501	 *  empty/partial manifest is itself the honest signal the primary's collector
502	 *  needs to raise, not something this endpoint should paper over. */
503	async function handleBackupManifest(_req, res) {
504	  const entries = [];
505	  for (const sub of ["platform", "hypervisor", "status"]) {
506	    const dir = path.join(BACKUP_ROOT, sub);
507	    let names;
508	    try {
509	      names = fs.readdirSync(dir);
510	    } catch {
511	      continue; // subdir doesn't exist on this node yet — not an error
512	    }
513	    for (const name of names) {
514	      const rel = `${sub}/${name}`;
515	      if (!BACKUP_REL_RE.test(rel)) continue; // silently skip anything not on the allowlist
516	      let st;
517	      try {
518	        st = fs.statSync(path.join(dir, name));
519	      } catch {
520	        continue;
521	      }
522	      if (!st.isFile()) continue;
523	      entries.push({ path: rel, size: st.size, mtimeMs: st.mtimeMs });
524	    }
525	  }
526	  sendJson(res, 200, { entries });
527	}
