529	/** Stream one backup file's raw bytes. `relPath` must match BACKUP_REL_RE
530	 *  (rules out traversal by construction — no `..`, no absolute path, no
531	 *  extension this platform doesn't itself produce) AND the resolved real
532	 *  path must land inside BACKUP_ROOT — same defense-in-depth shape as
533	 *  resolveSnippetPath() above, kept even though the regex alone should
534	 *  already be sufficient. */
535	async function handleBackupFile(_req, res, relPath) {
536	  if (!isStr(relPath, BACKUP_REL_RE)) return sendJson(res, 400, { error: "invalid path" });
537	  const full = path.join(BACKUP_ROOT, relPath);
538	  let real;
539	  try {
540	    real = fs.realpathSync(full);
541	  } catch {
542	    return sendJson(res, 404, { error: "not found" });
543	  }
544	  const rootReal = fs.realpathSync(BACKUP_ROOT);
545	  if (real !== rootReal && !real.startsWith(rootReal + path.sep)) {
546	    return sendJson(res, 400, { error: "path escapes backup root" });
547	  }
548	  let st;
549	  try {
550	    st = fs.statSync(real);
551	  } catch {
552	    return sendJson(res, 404, { error: "not found" });
553	  }
554	  if (!st.isFile()) return sendJson(res, 404, { error: "not found" });
555	  res.writeHead(200, {
556	    "Content-Type": "application/octet-stream",
557	    "Content-Length": st.size,
558	    "Content-Disposition": `attachment; filename="${path.basename(real)}"`,
559	  });
560	  fs.createReadStream(real).pipe(res);
561	}
