563	// ---- backup health (read-only) --------------------------------------------------
564	//
565	// One cheap GET that tells the primary everything it needs to judge THIS node's
566	// backups without SSH: timer state, the guest list, newest local archive per
567	// guest, backup-filesystem space, the last run's status and the host pressure
568	// numbers. READ-ONLY: it executes `systemctl show`, `pvesh get` (list), `pveversion`
569	// and, when present, the planner script (which only reads files) - nothing here
570	// can change a guest, a timer or a file. See lib/backup-node-health.ts for the type.
571	const BACKUP_TIMER_UNITS = ["nxeon-backup-run.timer", "nxeon-backup-vms.timer"];
572	const PLAN_SCRIPT = process.env.NXEON_BACKUP_PLAN_SCRIPT || "/opt/nxeon/scripts/backup/nxeon-backup-plan.py";
573	const VZDUMP_ARCHIVE_RE = /^vzdump-qemu-(\d+)-(\d{4})_(\d{2})_(\d{2})-(\d{2})_(\d{2})_(\d{2})\.vma(\.zst|\.gz|\.lzo)?$/;
574	
575	function execText(cmd, args, timeout) {
576	  return new Promise((resolve) => {
577	    execFile(cmd, args, { timeout: timeout || CMD_TIMEOUT_MS, maxBuffer: 8 * 1024 * 1024 }, (err, stdout) => resolve(err ? null : String(stdout)));
578	  });
579	}
580	function readTextSafe(p) {
581	  try { return fs.readFileSync(p, "utf8"); } catch { return null; }
582	}
583	function parsePsiLine(text) {
584	  const out = {};
585	  for (const line of (text || "").split("\n")) {
586	    const m = /^(some|full)\s+avg10=([\d.]+)\s+avg60=([\d.]+)\s+avg300=([\d.]+)/.exec(line);
587	    if (m) out[m[1]] = { avg10: Number(m[2]), avg60: Number(m[3]), avg300: Number(m[4]) };
588	  }
589	  return out;
590	}
591	
592	async function handleBackupHealth(_req, res) {
593	  const timers = [];
594	  for (const unit of BACKUP_TIMER_UNITS) {
595	    const txt = await execText("systemctl", ["show", unit, "-p", "LoadState,UnitFileState,ActiveState,LastTriggerUSec,NextElapseUSecRealtime"], 8000);
596	    if (!txt) continue;
597	    const kv = {};
598	    for (const l of txt.split("\n")) { const i = l.indexOf("="); if (i > 0) kv[l.slice(0, i)] = l.slice(i + 1); }
599	    if (kv.LoadState === "not-found") continue; // not installed on this node
600	    const last = Date.parse(kv.LastTriggerUSec || "");
601	    timers.push({
602	      name: unit,
603	      enabled: kv.UnitFileState === "enabled" || kv.UnitFileState === "enabled-runtime" || kv.UnitFileState === "static",
604	      active: kv.ActiveState === "active",
605	      lastTriggerMs: Number.isFinite(last) ? last : null,
606	    });
607	  }
608	
609	  let vms = [];
610	  const vmJson = await execText("pvesh", ["get", "/nodes/localhost/qemu", "--output-format", "json"], 30_000);
611	  let vmsOk = false;
612	  if (vmJson) {
613	    try {
614	      vms = JSON.parse(vmJson).map((v) => ({ vmid: v.vmid, name: v.name || "", status: v.status || "", template: v.template ? 1 : 0, tags: v.tags || "", maxdisk: v.maxdisk || 0 }));
615	      vmsOk = true;
616	    } catch { /* leave empty; vmsOk=false tells the caller the list is unreliable */ }
617	  }
618	
619	  const newestByVmid = {};
620	  let largest = 0;
621	  let totalBytes = 0;
622	  try {
623	    for (const name of fs.readdirSync(path.join(BACKUP_ROOT, "platform"))) {
624	      const m = VZDUMP_ARCHIVE_RE.exec(name);
625	      if (!m) continue;
626	      let st; try { st = fs.statSync(path.join(BACKUP_ROOT, "platform", name)); } catch { continue; }
627	      const ts = Date.UTC(+m[2], +m[3] - 1, +m[4], +m[5], +m[6], +m[7]);
628	      if (!newestByVmid[m[1]] || ts > newestByVmid[m[1]]) newestByVmid[m[1]] = ts;
629	      if (st.size > largest) largest = st.size;
630	      totalBytes += st.size;
631	    }
632	  } catch { /* no platform dir yet */ }
633	
634	  let hypervisorNewestMs = null;
635	  for (const [sub, re] of [["hypervisor", /^hypervisor-.*-(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})\.tar\.gz$/], ["platform", /^host-config-(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})\.tar\.gz$/]]) {
636	    try {
637	      for (const name of fs.readdirSync(path.join(BACKUP_ROOT, sub))) {
638	        const m = re.exec(name);
639	        if (!m) continue;
640	        const ts = Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6]);
641	        if (hypervisorNewestMs === null || ts > hypervisorNewestMs) hypervisorNewestMs = ts;
642	      }
643	    } catch { /* dir absent */ }
644	  }
645	
646	  let fsInfo = null;
647	  try {
648	    const st = fs.statfsSync(BACKUP_ROOT);
649	    fsInfo = { freeBytes: Number(st.bavail) * Number(st.bsize), totalBytes: Number(st.blocks) * Number(st.bsize) };
650	  } catch { /* backup root missing */ }
651	
652	  let runStatus = null;
653	  try { runStatus = JSON.parse(readTextSafe(path.join(BACKUP_ROOT, "status", "backup-run.json")) || "null"); } catch { /* ignore */ }
654	
655	  // The planner is the single source of truth for guest classes/cadences. Optional: a node that has not
656	  // been given the v2 scripts yet reports plan:null and the primary falls back to strict defaults.
657	  let plan = null;
658	  if (fs.existsSync(PLAN_SCRIPT)) {
659	    const t = await execText("python3", [PLAN_SCRIPT, "--archives-dir", path.join(BACKUP_ROOT, "platform")], 60_000);
660	    try { plan = t ? JSON.parse(t) : null; } catch { plan = null; }
661	  }
662	
663	  const loadavg = (readTextSafe("/proc/loadavg") || "").split(" ").slice(0, 3).map(Number);
664	  const mem = {};
665	  for (const l of (readTextSafe("/proc/meminfo") || "").split("\n")) {
666	    const m = /^(MemAvailable|SwapTotal|SwapFree):\s+(\d+) kB/.exec(l);
667	    if (m) mem[m[1]] = Number(m[2]) * 1024;
668	  }
669	  const pveversion = ((await execText("pveversion", [], 8000)) || "").trim() || null;
670	
671	  sendJson(res, 200, {
672	    node: require("node:os").hostname(),
673	    at: Date.now(),
674	    kernel: require("node:os").release(),
675	    pveversion,
676	    timers,
677	    vmsOk,
678	    vms,
679	    plan,
680	    newestArchiveByVmid: newestByVmid,
681	    localArchiveBytes: totalBytes,
682	    largestArchiveBytes: largest,
683	    hypervisorNewestMs,
684	    backupFs: fsInfo,
685	    runStatus,
686	    pressure: {
687	      cpu: parsePsiLine(readTextSafe("/proc/pressure/cpu")),
688	      io: parsePsiLine(readTextSafe("/proc/pressure/io")),
689	      memory: parsePsiLine(readTextSafe("/proc/pressure/memory")),
690	    },
691	    loadavg,
692	    memAvailableBytes: mem.MemAvailable ?? null,
693	    swapUsedBytes: mem.SwapTotal != null && mem.SwapFree != null ? mem.SwapTotal - mem.SwapFree : null,
694	  });
695	}
