699	async function route(req, res) {
700	  const url = new URL(req.url, `https://${req.headers.host || "localhost"}`);
701	  const { pathname, searchParams } = url;
702	
703	  if (req.method === "GET" && pathname === "/v1/health") return handleHealth(req, res);
704	
705	  if (req.method === "POST" && pathname === "/v1/nat/ensure-chain") return handleEnsureChain(req, res, await readBody(req));
706	
707	  const chainMatch = /^\/v1\/nat\/chain\/([^/]+)$/.exec(pathname);
708	  if (req.method === "GET" && chainMatch) return handleListChain(req, res, decodeURIComponent(chainMatch[1]));
709	
710	  if (req.method === "POST" && pathname === "/v1/nat/rule") return handleAddRule(req, res, await readBody(req));
711	  if (req.method === "DELETE" && pathname === "/v1/nat/rule") return handleDeleteRule(req, res, await readBody(req));
712	
713	  if (req.method === "POST" && pathname === "/v1/snippet") return handleWriteSnippet(req, res, await readBody(req));
714	  if (req.method === "DELETE" && pathname === "/v1/snippet") return handleDeleteSnippet(req, res, await readBody(req));
715	
716	  if (req.method === "GET" && pathname === "/v1/iptables/dnat-check") return handleDnatCheck(req, res, searchParams.get("address"));
717	
718	  if (req.method === "GET" && pathname === "/v1/backup/manifest") return handleBackupManifest(req, res);
719	  if (req.method === "GET" && pathname === "/v1/backup/health") return handleBackupHealth(req, res);
720	  if (req.method === "GET" && pathname === "/v1/backup/file") return handleBackupFile(req, res, searchParams.get("path"));
721	
722	  // VM move transport (see the ZFS section above).
723	  if (req.method === "GET" && pathname === "/v1/zfs/dataset") return handleZfsDataset(req, res, searchParams.get("dataset"));
724	  if (req.method === "POST" && pathname === "/v1/zfs/snapshot") return handleZfsSnapshot(req, res, await readBody(req));
725	  if (req.method === "DELETE" && pathname === "/v1/zfs/snapshot") return handleZfsDeleteSnapshot(req, res, await readBody(req));
726	  if (req.method === "DELETE" && pathname === "/v1/zfs/dataset") return handleZfsDestroyDataset(req, res, await readBody(req));
727	  if (req.method === "POST" && pathname === "/v1/zfs/recv") return handleZfsRecv(req, res, searchParams.get("dataset"));
728	  if (req.method === "GET" && pathname === "/v1/zfs/send") return handleZfsSend(req, res, searchParams.get("dataset"), searchParams.get("snap"), searchParams.get("from"), searchParams.get("token"));
729	  if (req.method === "GET" && pathname === "/v1/net/neigh") return handleNeigh(req, res);
730	  if (req.method === "GET" && pathname === "/v1/zfs/vm-config") return handleVmConfigExists(req, res, searchParams.get("vmid"));
731	
732	  sendJson(res, 404, { error: "not found" });
733	}
734	
735	// `requestTimeout: 0` — Node's default (300 s) would cut a multi-GB
736	// /v1/zfs/recv upload mid-stream. Nothing else here runs long; the control
737	// endpoints are still bounded by their own exec timeouts.
738	const server = https.createServer({ key: fs.readFileSync(TLS_KEY), cert: fs.readFileSync(TLS_CERT), requestTimeout: 0 }, (req, res) => {
739	  if (!checkAuth(req)) {
740	    sendJson(res, 401, { error: "unauthorized" });
741	    return;
742	  }
743	  route(req, res).catch((e) => {
744	    console.error("[node-agent] request error:", e && e.message ? e.message : e);
745	    try {
746	      sendJson(res, 500, { error: String((e && e.message) || e).slice(0, 300) });
747	    } catch {
748	      /* response already sent/closed */
749	    }
750	  });
751	});
752	
753	server.listen(PORT, () => {
754	  console.log(`[node-agent] listening on :${PORT}`);
755	});
