1	/**
2	 * Node-agent client: talks to the small HTTPS service (node-agent/index.js)
3	 * that runs on every NON-PRIMARY node, giving the primary's worker a narrow,
4	 * token-authenticated way to touch that node's own NAT table and cloud-init
5	 * snippet storage — the two host-level operations the worker cannot do
6	 * remotely any other way (see docs/DOCUMENTATION.md's "Multi-node synergy").
7	 *
8	 * TOKEN DIRECTION: the primary is the CALLER here (unlike telemetry tokens,
9	 * where a server/node calls INTO the primary). So the primary must be able to
10	 * present the token on every request, not just verify one it already
11	 * receives — it is stored encrypted (lib/crypto-box.ts, AUTH_SECRET-derived),
12	 * not hashed, on `Node.agentTokenEnc`. The agent's own side stores its copy
13	 * in a local root-only file on that node (never in this app's database) and
14	 * compares incoming requests against it with a constant-time check — see
15	 * node-agent/index.js.
16	 *
17	 * TRANSPORT: HTTPS with a self-signed cert (generated once at onboard time),
18	 * verified the same way this codebase already trusts a node's Proxmox API
19	 * (lib/proxmox.ts's `insecureAgent`, rejectUnauthorized: false) — encrypts the
20	 * wire without needing a CA-issued cert for a bare IP with no public DNS name.
21	 * A leaked token's blast radius is deliberately narrow: NAT rules and
22	 * cloud-init snippets for ONE node, never a shell, never the database.
23	 */
24	import { Agent, fetch as undiciFetch } from "undici";
25	import { randomBytes } from "node:crypto";
26	import { encryptSecret, decryptSecret } from "./crypto-box";
27	import { db } from "./db";
28	import type { NatRule } from "./nat-rules";
29	
30	const insecureAgent = new Agent({ connect: { rejectUnauthorized: false } });
31	
32	const REQUEST_TIMEOUT_MS = 15_000;
33	
34	/** Generate a fresh raw agent token. Shown to the operator exactly once
35	 *  (the onboarding script prints it; the admin "Add node" form is where it's
36	 *  pasted in and immediately encrypted — never redisplayed after that). */
37	export function generateNodeAgentToken(): string {
38	  return randomBytes(32).toString("base64url");
39	}
40	
41	/** Encrypt a raw token for storage on `Node.agentTokenEnc`. */
42	export function encryptNodeAgentToken(token: string): string {
43	  return encryptSecret(token);
44	}
45	
46	/** The subset of `Node` every agent call needs. */
47	export type AgentNode = {
48	  id: string;
49	  name: string;
50	  publicIp: string;
51	  agentPort: number;
52	  agentTokenEnc: string | null;
53	};
54	
55	/** Decrypt this node's agent token, or null if none is configured yet. */
56	export function nodeAgentToken(node: Pick<AgentNode, "agentTokenEnc">): string | null {
57	  return decryptSecret(node.agentTokenEnc);
58	}
59	
60	export class NodeAgentError extends Error {
61	  constructor(message: string, public readonly node: string) {
62	    super(message);
63	    this.name = "NodeAgentError";
64	  }
65	}
66	
67	/**
68	 * Low-level call to a node's agent. Throws NodeAgentError with a message safe
69	 * to surface in worker logs (never includes the token).
70	 */
71	async function agentRequest(
72	  node: AgentNode,
73	  method: "GET" | "POST" | "DELETE",
74	  path: string,
75	  body?: unknown
76	): Promise<any> {
77	  const token = nodeAgentToken(node);
78	  if (!token) {
79	    throw new NodeAgentError(`node "${node.name}" has no agent token configured — see /admin/nodes/${node.id}`, node.name);
80	  }
81	  const url = `https://${node.publicIp}:${node.agentPort}${path}`;
82	  const doFetch = () =>
83	    undiciFetch(url, {
84	      method,
85	      headers: {
86	        Authorization: `Bearer ${token}`,
87	        ...(body !== undefined ? { "Content-Type": "application/json" } : {}),
88	      },
89	      body: body !== undefined ? JSON.stringify(body) : undefined,
90	      dispatcher: insecureAgent,
91	      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
92	    });
93	  let res: Awaited<ReturnType<typeof doFetch>>;
94	  try {
95	    res = await doFetch();
96	  } catch (e: any) {
97	    throw new NodeAgentError(`could not reach node-agent on "${node.name}" (${url}): ${e?.message ?? e}`, node.name);
98	  }
99	  const text = await res.text().catch(() => "");
100	  if (!res.ok) {
101	    throw new NodeAgentError(`node-agent on "${node.name}" returned ${res.status}: ${text.slice(0, 300)}`, node.name);
102	  }
103	  if (!text) return null;
104	  try {
105	    return JSON.parse(text);
106	  } catch {
107	    throw new NodeAgentError(`node-agent on "${node.name}" returned a non-JSON response: ${text.slice(0, 200)}`, node.name);
108	  }
109	}
110	
111	/** `GET /v1/health` — used by testNode() and the NAT dispatch's own sanity check. */
112	export async function agentHealth(node: AgentNode): Promise<{ ok: boolean; version?: number }> {
113	  return agentRequest(node, "GET", "/v1/health");
114	}
