203	/** Pipe a (zstd-compressed) zfs send stream INTO this node's `zfs receive`. Resolves when the agent confirms the receive exited 0. */
204	export async function agentZfsRecv(node: AgentNode, dataset: string, body: import("node:stream").Readable): Promise<void> {
205	  const token = agentAuthOrThrow(node);
206	  const url = `https://${node.publicIp}:${node.agentPort}/v1/zfs/recv?dataset=${encodeURIComponent(dataset)}`;
207	  let res: Awaited<ReturnType<typeof undiciFetch>>;
208	  try {
209	    res = await undiciFetch(url, {
210	      method: "POST",
211	      headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/octet-stream" },
212	      body: body as any,
213	      duplex: "half",
214	      dispatcher: insecureAgent,
215	      signal: undefined,
216	    } as any);
217	  } catch (e: any) {
218	    throw new NodeAgentError(`zfs recv to "${node.name}" failed in transit: ${e?.message ?? e}`, node.name);
219	  }
220	  const text = await res.text().catch(() => "");
221	  if (!res.ok) throw new NodeAgentError(`node-agent on "${node.name}" rejected zfs recv (${res.status}): ${text.slice(0, 300)}`, node.name);
222	}
