224	/** Open a (zstd-compressed) zfs send stream FROM this node. The caller must consume it fully; a truncated body means the remote send failed. */
225	export async function agentZfsSendStream(node: AgentNode, dataset: string, snap: string, from?: string | null, resumeToken?: string | null): Promise<import("node:stream").Readable> {
226	  const token = agentAuthOrThrow(node);
227	  const qs = new URLSearchParams({ dataset, snap, ...(from ? { from } : {}), ...(resumeToken ? { token: resumeToken } : {}) });
228	  const url = `https://${node.publicIp}:${node.agentPort}/v1/zfs/send?${qs}`;
229	  let res: Awaited<ReturnType<typeof undiciFetch>>;
230	  try {
231	    res = await undiciFetch(url, { method: "GET", headers: { Authorization: `Bearer ${token}` }, dispatcher: insecureAgent, signal: undefined });
232	  } catch (e: any) {
233	    throw new NodeAgentError(`could not open zfs send from "${node.name}": ${e?.message ?? e}`, node.name);
234	  }
235	  if (!res.ok || !res.body) {
236	    const text = await res.text().catch(() => "");
237	    throw new NodeAgentError(`node-agent on "${node.name}" refused zfs send (${res.status}): ${text.slice(0, 300)}`, node.name);
238	  }
239	  const { Readable } = await import("node:stream");
240	  return Readable.fromWeb(res.body as any);
241	}
