263	/**
264	 * Stream one backup file's raw bytes off a node's agent into `destPath`.
265	 * Deliberately bypasses agentRequest() (which JSON-parses every response) —
266	 * these are multi-GB vzdump archives, not small control-plane payloads, so
267	 * this goes straight to a Node stream pipeline instead of buffering the
268	 * whole file in memory.
269	 */
270	export async function agentDownloadBackupFile(node: AgentNode, relPath: string, destPath: string): Promise<void> {
271	  const token = nodeAgentToken(node);
272	  if (!token) {
273	    throw new NodeAgentError(`node "${node.name}" has no agent token configured — see /admin/nodes/${node.id}`, node.name);
274	  }
275	  const url = `https://${node.publicIp}:${node.agentPort}/v1/backup/file?path=${encodeURIComponent(relPath)}`;
276	  let res: Awaited<ReturnType<typeof undiciFetch>>;
277	  try {
278	    res = await undiciFetch(url, {
279	      method: "GET",
280	      headers: { Authorization: `Bearer ${token}` },
281	      dispatcher: insecureAgent,
282	      // Large archives over a public-internet link: a per-request timeout
283	      // would kill a legitimate multi-GB transfer partway through, so this
284	      // one call is unbounded — the caller (the collector's own per-node
285	      // budget) is what actually bounds a hung node.
286	      signal: undefined,
287	    });
288	  } catch (e: any) {
289	    throw new NodeAgentError(`could not reach node-agent on "${node.name}" for ${relPath}: ${e?.message ?? e}`, node.name);
290	  }
291	  if (!res.ok || !res.body) {
292	    const text = await res.text().catch(() => "");
293	    throw new NodeAgentError(`node-agent on "${node.name}" returned ${res.status} for ${relPath}: ${text.slice(0, 300)}`, node.name);
294	  }
295	  const { mkdir, rename, rm } = await import("node:fs/promises");
296	  const { createWriteStream } = await import("node:fs");
297	  const { Readable } = await import("node:stream");
298	  const { pipeline } = await import("node:stream/promises");
299	  const path = await import("node:path");
300	  await mkdir(path.dirname(destPath), { recursive: true });
301	  const tmp = `${destPath}.partial`;
302	  try {
303	    await pipeline(Readable.fromWeb(res.body as any), createWriteStream(tmp, { mode: 0o600 }));
304	  } catch (e) {
305	    await rm(tmp, { force: true });
306	    throw e;
307	  }
308	  await rename(tmp, destPath);
309	}
