  addressChanged  Boolean      @default(false)
  keepSourceUntil DateTime?
  sourceCleanedAt DateTime?
  startedAt       DateTime?
  finishedAt      DateTime?
  createdAt       DateTime     @default(now())
  updatedAt       DateTime     @updatedAt

  @@index([serverId])
  @@index([status])
}

