1997	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
1998	    await notify(
1999	      server.userId,
2000	      `Server ${server.hostname} reinstalled (sandbox)`,
2001	      "The sandbox server was reinstalled (no real VM was touched).",
2002	      `/dashboard/servers/${server.id}`
2003	    );
2004	    return;
2005	  }
2006	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
2007	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
2008	  // EVERY disk the vmid owns, including attached block-storage Volume disks
2009	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
2010	  // by that vmid, and both purge and the default destroy (which removes disks
2011	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
2012	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
2013	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
2014	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
2015	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
2016	  // can be re-attached after the reinstall. This runs BEFORE any status change or
2017	  // destructive call, so a blocked reinstall touches nothing.
2018	  //
2019	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
2020	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
2021	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
2022	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
2023	  // let the worst path through: fill a volume, Detach (the UI says "Data is
2024	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
2025	  // Detaching is therefore NOT sufficient protection, and telling the customer to
2026	  // detach was wrong advice; they must delete the volume (which destroys just
2027	  // that disk, deliberately) or move it to another server first.
2028	  const pinnedVolumes = await db.volume.findMany({
2029	    where: { serverId: server.id },
2030	  });
