2032	  const realPinned = pinnedVolumes.filter(
2033	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
2034	  );
2035	  if (realPinned.length > 0) {
2036	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
