async function powerOff(conn: PveClient, vmid: number): Promise<void> {
  try {
    const st = await conn.vmStatus(vmid);
    if (st?.status === "stopped") return;
  } catch {
    /* fall through to stop */
  }
  try {
    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/shutdown`, { timeout: 60 });
    await conn.waitForTask(upid, 120_000);
  } catch {
    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
    await conn.waitForTask(upid);
  }
}

async function powerOn(conn: PveClient, vmid: number): Promise<void> {
  try {
    const st = await conn.vmStatus(vmid);
    if (st?.status === "running") return;
  } catch {
    /* try start anyway */
  }
  const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
  await conn.waitForTask(upid);
}

type NodeRow = NonNullable<Awaited<ReturnType<typeof nodeRowFor>>>;

/** Put a server (whose dedicated IP has just been released) onto shared NAT. */
async function moveToNat(conn: PveClient, server: LoadedServer, nodeRow: NodeRow): Promise<{ ip: string; sshPort: number }> {
  const fresh = await db.server.findUnique({ where: { id: server.id }, select: { ipAddress: true, sshPort: true } });
  const ip = fresh?.ipAddress && fresh.ipAddress.startsWith(nodeRow.subnetPrefix) ? fresh.ipAddress : await allocateIp(server.nodeId, server.id);
