// Exclusive CPU reservations — the PURE half (no db, no network, client-safe).
//
// WHY THIS EXISTS (2026-10-06). A paying customer (syntech-vps, VM 667 on
// node-6) was promised in writing three DEDICATED physical cores that no other
// customer's VM is ever scheduled on, while node-6 keeps taking other
// customers. Proxmox's per-VM `affinity` option (a cpuset the VM's QEMU
// process is confined to) is the mechanism; the platform's job is to make sure
//   (1) the reserved VM is confined to its cores,
//   (2) EVERY other VM on that node is confined to the complement ("shared
//       pool") BEFORE it ever starts — no window where a new VM runs on all
//       threads (the interim node-6 timer had a ≤30 s gap),
//   (3) drift (a manual `qm set`, a restore, a rollback) is found and fixed,
//   (4) the scheduler knows the node's shared pool is small.
//
// Source of truth = the `CpuReservation` table (one row per reserved server,
// nodeId + cpuset). Everything here is derived from those rows plus the
// node's real CPU topology (Node.cpuTopology, read from /sys by the node
// agent or, on the primary, by the worker itself).
//
// The node agent (node-agent/index.js) carries its own copy of the cpuset
// parser/formatter — it is a dependency-free single file. KEEP IN SYNC;
// test/cpu-reservation.test.ts asserts both produce identical output.

/** One logical CPU (hardware thread) as the kernel reports it. */
export type CpuThread = {
  cpu: number;
  /** Physical core id (per socket) — /sys/.../topology/core_id. */
  core: number;
  /** Socket — /sys/.../topology/physical_package_id. */
  socket: number;
  /** thread_siblings_list, canonical cpuset string (e.g. "0,4"). */
  siblings: string;
};

/**
 * What we persist on Node.cpuTopology. `threads` is empty when the only source
 * was the Proxmox API (thread count known, sibling map not) — such a node can
 * be SCHEDULED CPU-aware but cannot take a reservation (whole-core validation
 * needs the sibling map).
 */
export type CpuTopology = {
  source: "agent" | "local" | "pve";
  threadCount: number;
  threads: CpuThread[];
  /** /sys/devices/system/cpu/online, canonical. */
  online?: string;
  model?: string | null;
};

export type PhysicalCore = {
  /** Stable key: the canonical sibling cpuset, e.g. "0,4". */
  key: string;
  socket: number;
  core: number;
  threads: number[];
};

export type ReservationLike = { id?: string; serverId: string; cpuset: string; label?: string | null };

const CPUSET_RE = /^\d{1,4}(?:-\d{1,4})?(?:,\d{1,4}(?:-\d{1,4})?)*$/;
/** Hard ceiling on a cpu index we will ever accept (Linux NR_CPUS-ish). */
export const MAX_CPU_INDEX = 1023;

/**
 * Strict cpuset parser ("0-2,4-6" → [0,1,2,4,5,6]). Returns null for anything
 * that is not exactly digits, commas and ascending ranges — no spaces, no
 * signs, no empty items, no reversed ranges, nothing above MAX_CPU_INDEX. The
 * result is sorted and de-duplicated.
 */
export function parseCpuset(raw: unknown): number[] | null {
  if (typeof raw !== "string" || raw.length === 0 || raw.length > 512) return null;
  if (!CPUSET_RE.test(raw)) return null;
  const out = new Set<number>();
  for (const part of raw.split(",")) {
    const [a, b] = part.split("-");
    const lo = Number(a);
    const hi = b === undefined ? lo : Number(b);
    if (!Number.isInteger(lo) || !Number.isInteger(hi) || lo > hi || hi > MAX_CPU_INDEX) return null;
    for (let i = lo; i <= hi; i++) out.add(i);
  }
  return [...out].sort((x, y) => x - y);
}

/** Canonical cpuset string ([0,1,2,4,5,6] → "0-2,4-6"; [3,7] → "3,7"). */
export function formatCpuset(cpus: Iterable<number>): string {
  const s = [...new Set(cpus)].filter((n) => Number.isInteger(n) && n >= 0).sort((a, b) => a - b);
  const parts: string[] = [];
  for (let i = 0; i < s.length; ) {
    let j = i;
    while (j + 1 < s.length && s[j + 1] === s[j] + 1) j++;
    // Two adjacent cpus are written "a,b" (what Proxmox and taskset print), three+ as a range.
    if (j === i) parts.push(String(s[i]));
    else if (j === i + 1) parts.push(`${s[i]},${s[j]}`);
    else parts.push(`${s[i]}-${s[j]}`);
    i = j + 1;
  }
  return parts.join(",");
}

/** Normalise a cpuset string to canonical form, or null when unparseable. */
export function canonicalCpuset(raw: unknown): string | null {
  const c = parseCpuset(raw);
  return c && c.length > 0 ? formatCpuset(c) : null;
}

export function sameCpuset(a: string | null | undefined, b: string | null | undefined): boolean {
  if (!a && !b) return true;
  if (!a || !b) return false;
  return canonicalCpuset(a) === canonicalCpuset(b);
}

/** Group the topology's threads into physical cores (by sibling set). */
export function physicalCores(topo: CpuTopology | null | undefined): PhysicalCore[] {
  if (!topo || !Array.isArray(topo.threads) || topo.threads.length === 0) return [];
  const byKey = new Map<string, PhysicalCore>();
  for (const t of topo.threads) {
    const sib = parseCpuset(t.siblings);
    const threads = sib && sib.includes(t.cpu) ? sib : [t.cpu];
    const key = formatCpuset(threads);
    const cur = byKey.get(key);
    if (cur) {
      for (const x of threads) if (!cur.threads.includes(x)) cur.threads.push(x);
      cur.threads.sort((a, b) => a - b);
    } else {
      byKey.set(key, { key, socket: t.socket, core: t.core, threads: [...threads] });
    }
  }
  return [...byKey.values()].sort((a, b) => a.socket - b.socket || a.core - b.core || a.threads[0] - b.threads[0]);
}

/** Every thread the topology knows about. */
export function allThreads(topo: CpuTopology | null | undefined): number[] {
  if (!topo) return [];
  if (topo.threads?.length) return [...new Set(topo.threads.map((t) => t.cpu))].sort((a, b) => a - b);
  const online = parseCpuset(topo.online ?? "");
  if (online) return online;
  return Array.from({ length: Math.max(0, topo.threadCount | 0) }, (_, i) => i);
}

export type ReservationCheck = {
  ok: boolean;
  /** Canonical form of the requested set (null when unparseable). */
  cpuset: string | null;
  cpus: number[];
  /** Physical cores the set covers (only meaningful when ok). */
  cores: PhysicalCore[];
  errors: string[];
  warnings: string[];
};

/**
 * Validate a requested reservation against the node's REAL topology and the
 * node's other reservations. Rules (all hard errors):
 *   - the set parses and is non-empty;
 *   - the topology has a sibling map (source agent/local, not pve-only);
 *   - every cpu exists on the node;
 *   - only WHOLE physical cores: every SMT sibling of a chosen thread is in the
 *     set (reserving one hyperthread would leave its sibling — the same
 *     physical core — in the shared pool, which is not "dedicated");
 *   - no overlap with any other reservation on the node;
 *   - at least `minSharedCores` whole physical cores (default 1) stay in the
 *     shared pool — the host itself (ZFS, pveproxy, the agent) and every other
 *     VM need somewhere to run. Never reserve the last core.
 * Warnings (allowed, shown to the admin): the VM's vCPU count differs from the
 * reserved thread count.
 */
export function validateReservation(args: {
  topology: CpuTopology | null | undefined;
  cpuset: string;
  /** Other reservations on the SAME node (the one being replaced excluded). */
  others: ReservationLike[];
  vcpu?: number | null;
  minSharedCores?: number;
}): ReservationCheck {
  const errors: string[] = [];
  const warnings: string[] = [];
  const cpus = parseCpuset(args.cpuset) ?? [];
  const canonical = cpus.length ? formatCpuset(cpus) : null;
  const res = (extra?: Partial<ReservationCheck>): ReservationCheck => ({
    ok: errors.length === 0,
    cpuset: canonical,
    cpus,
    cores: [],
    errors,
    warnings,
    ...extra,
  });
  if (!parseCpuset(args.cpuset)) {
    errors.push(`"${String(args.cpuset).slice(0, 40)}" is not a valid cpuset (use e.g. 0-2,4-6).`);
    return res();
  }
  if (cpus.length === 0) {
    errors.push("The reservation is empty.");
    return res();
  }
  const cores = physicalCores(args.topology);
  if (cores.length === 0) {
    errors.push("This node's CPU topology (which threads share a physical core) has not been read yet. Read it first (node page → CPU reservations → Read topology); a node agent v5+ is required.");
    return res();
  }
  const known = new Set(allThreads(args.topology));
  const missing = cpus.filter((c) => !known.has(c));
  if (missing.length) errors.push(`CPU ${formatCpuset(missing)} does not exist on this node (it has ${formatCpuset([...known])}).`);

  const chosen = new Set(cpus);
  const covered: PhysicalCore[] = [];
  for (const core of cores) {
    const inSet = core.threads.filter((t) => chosen.has(t));
    if (inSet.length === 0) continue;
    if (inSet.length !== core.threads.length) {
      const absent = core.threads.filter((t) => !chosen.has(t));
      errors.push(`Only whole physical cores can be reserved: thread ${formatCpuset(inSet)} shares a core with ${formatCpuset(absent)}, which must be included too.`);
    } else covered.push(core);
  }

  const taken = new Map<number, ReservationLike>();
  for (const o of args.others) for (const c of parseCpuset(o.cpuset) ?? []) taken.set(c, o);
  const overlap = cpus.filter((c) => taken.has(c));
  if (overlap.length) {
    const who = [...new Set(overlap.map((c) => taken.get(c)!.label || taken.get(c)!.serverId))].join(", ");
    errors.push(`CPU ${formatCpuset(overlap)} is already reserved (${who}).`);
  }

  const minShared = Math.max(1, Math.floor(args.minSharedCores ?? 1));
  const reservedAfter = new Set<number>([...taken.keys(), ...cpus]);
  const freeCores = cores.filter((c) => c.threads.every((t) => !reservedAfter.has(t)));
  if (freeCores.length < minShared) {
    errors.push(
      freeCores.length === 0
        ? "That would reserve the node's last physical core — the host and every other VM need at least one."
        : `At least ${minShared} whole physical core(s) must stay in the shared pool; this leaves ${freeCores.length}.`,
    );
  }

  if (args.vcpu && args.vcpu > 0 && errors.length === 0) {
    if (args.vcpu > cpus.length) warnings.push(`The VM has ${args.vcpu} vCPU but only ${cpus.length} reserved thread(s) — its vCPUs will contend with each other.`);
    else if (args.vcpu < cpus.length) warnings.push(`The VM has ${args.vcpu} vCPU for ${cpus.length} reserved thread(s) — some reserved threads will sit idle.`);
  }
  return res({ ok: errors.length === 0, cores: covered });
}

/** The shared pool: every thread no reservation holds. */
export function sharedCpus(topology: CpuTopology | null | undefined, reservations: ReservationLike[]): number[] {
  const reserved = new Set<number>();
  for (const r of reservations) for (const c of parseCpuset(r.cpuset) ?? []) reserved.add(c);
  return allThreads(topology).filter((c) => !reserved.has(c));
}

/**
 * Desired affinity for one VM on a node. `null` = the platform does not manage
 * affinity on this node (no reservations): leave the VM unconfined. A node WITH
 * reservations manages every non-template VM: the owner of a reservation gets
 * its set, everything else gets the shared pool. Throws when the node has
 * reservations but no usable shared pool (validation forbids it; a corrupt row
 * must fail closed, never silently fall back to "all threads").
 */
export function desiredAffinity(args: {
  vmid: number;
  isTemplate?: boolean;
  topology: CpuTopology | null | undefined;
  /** Reservations on THIS node, each resolved to its server's current vmid (null = not provisioned). */
  reservations: (ReservationLike & { vmid: number | null })[];
}): { cpuset: string | null; reason: "unmanaged" | "template" | "reserved" | "shared" } {
  if (args.reservations.length === 0) return { cpuset: null, reason: "unmanaged" };
  if (args.isTemplate) return { cpuset: null, reason: "template" };
  const own = args.reservations.find((r) => r.vmid === args.vmid);
  if (own) {
    const c = canonicalCpuset(own.cpuset);
    if (!c) throw new Error(`reservation ${own.id ?? own.serverId} has an unparseable cpuset "${own.cpuset}"`);
    return { cpuset: c, reason: "reserved" };
  }
  const shared = sharedCpus(args.topology, args.reservations);
  if (shared.length === 0) throw new Error("node has CPU reservations but no shared pool (topology missing or every thread reserved) — refusing to place a VM");
  return { cpuset: formatCpuset(shared), reason: "shared" };
}

/** What the node reports for one VM (agent GET /v1/cpu/affinity). */
export type VmAffinityState = {
  vmid: number;
  template: boolean;
  running: boolean;
  /** Effective config value (pending applied), canonical, or null when unset. */
  configAffinity: string | null;
  /** Live per-thread allowed sets (empty when stopped). */
  threads: { tid: number; cpus: string }[];
};

export type AffinityDrift = {
  vmid: number;
  desired: string | null;
  configOk: boolean;
  /** Threads whose live set differs from the desired set (only checked when desired != null). */
  badThreads: { tid: number; cpus: string }[];
};

/** Compare desired vs actual for one VM. `desired === null` → only the config is compared (must be unset). */
export function affinityDrift(desired: string | null, actual: VmAffinityState): AffinityDrift {
  const configOk = sameCpuset(desired, actual.configAffinity);
  const badThreads = desired === null ? [] : actual.threads.filter((t) => !sameCpuset(t.cpus, desired));
  return { vmid: actual.vmid, desired, configOk, badThreads };
}

/**
 * Isolation violations: any VM other than a reservation's owner that can run
 * (by config or live) on one of that reservation's threads. This is the
 * condition the admin alert exists for — "a reserved VM's cores were found
 * shared". Reported per reservation.
 */
export function findSharing(
  reservations: (ReservationLike & { vmid: number | null })[],
  vms: VmAffinityState[],
  allNodeThreads: number[],
): { reservation: ReservationLike & { vmid: number | null }; offenders: { vmid: number; where: "config" | "live"; cpus: string }[] }[] {
  const out: ReturnType<typeof findSharing> = [];
  for (const r of reservations) {
    const rs = new Set(parseCpuset(r.cpuset) ?? []);
    const offenders: { vmid: number; where: "config" | "live"; cpus: string }[] = [];
    for (const vm of vms) {
      if (vm.template || vm.vmid === r.vmid) continue;
      // An unset config affinity means "every thread" once the VM starts.
      const cfg = vm.configAffinity ? parseCpuset(vm.configAffinity) ?? allNodeThreads : allNodeThreads;
      if (cfg.some((c) => rs.has(c))) offenders.push({ vmid: vm.vmid, where: "config", cpus: vm.configAffinity ?? "all" });
      for (const t of vm.threads) {
        const live = parseCpuset(t.cpus) ?? allNodeThreads;
        if (live.some((c) => rs.has(c))) {
          offenders.push({ vmid: vm.vmid, where: "live", cpus: t.cpus });
          break;
        }
      }
    }
    if (offenders.length) out.push({ reservation: r, offenders });
  }
  return out;
}

