// CPU-aware placement — the PURE half of lib/node-capacity.ts's scheduler
// (no db, no network) so the scoring rules are unit-testable.
//
// Before 2026-10-06 scheduleNode() picked purely on committed RAM and ignored
// CPU. With exclusive CPU reservations (lib/cpu-reservation.ts) a node can
// have lots of free RAM but only a tiny shared CPU pool — node-6 has 32 GB
// left but, with syntech-vps holding 3 of its 4 physical cores, only 2 shared
// threads for the host and every other VM. RAM-only scoring would keep
// packing VMs onto those 2 threads.
//
// Modes (Setting `cpu_sched_mode`):
//   off   — exactly the legacy RAM-only behaviour (rollback switch).
//   guard — legacy RAM scoring, plus a HARD cap on nodes that have
//           reservations: the VM must fit the shared pool's vCPU budget
//           (sharedThreads × ratio). Nodes without reservations unchanged.
//   score — (default) guard, plus candidates are ranked on BOTH dimensions:
//           the node whose busier dimension (RAM or CPU) would be lowest after
//           placing the VM wins. CPU only RANKS on nodes without
//           reservations — it never makes such a node "full" — so no region's
//           customer-visible availability changes because of CPU overcommit
//           alone (vCPU overcommit is normal; node-4 runs ~5 vCPU/thread today).
//
// Ratio (Setting `cpu_overcommit_ratio`, default 4): vCPU the platform will
// commit per hardware thread of the pool.

export type CpuSchedMode = "off" | "guard" | "score";

export const CPU_SCHED_DEFAULT_MODE: CpuSchedMode = "score";
export const CPU_OVERCOMMIT_DEFAULT_RATIO = 4;

export function parseCpuSchedMode(raw: string | null | undefined): CpuSchedMode {
  const v = String(raw ?? "").trim().toLowerCase();
  return v === "off" || v === "guard" || v === "score" ? v : CPU_SCHED_DEFAULT_MODE;
}

/** Clamp to a sane ratio (0.5 .. 32); anything unparseable → default. */
export function parseOvercommitRatio(raw: string | number | null | undefined): number {
  const n = typeof raw === "number" ? raw : Number(String(raw ?? "").trim());
  if (!Number.isFinite(n) || n <= 0) return CPU_OVERCOMMIT_DEFAULT_RATIO;
  return Math.min(32, Math.max(0.5, n));
}

/** CPU facts for one candidate node, computed by the caller from the DB. */
export type NodeCpuFacts = {
  /** Threads in the pool new VMs land on: the SHARED pool when the node has reservations, else all threads. Null = unknown (no topology). */
  poolThreads: number | null;
  /** vCPU already committed to that pool (non-reserved servers on the node). */
  committedVcpu: number;
  hasReservations: boolean;
};

export type CpuVerdict = {
  /** Projected % of the pool's vCPU budget after this VM (null = unknown). */
  projectedPct: number | null;
  /** vCPU budget of the pool (poolThreads × ratio), null = unknown. */
  budgetVcpu: number | null;
  /** Hard refusal (only ever for a node with reservations, in guard/score). */
  refused: boolean;
  reason: string | null;
};

export function cpuVerdict(facts: NodeCpuFacts, planVcpu: number, ratio: number, mode: CpuSchedMode): CpuVerdict {
  if (mode === "off") return { projectedPct: null, budgetVcpu: null, refused: false, reason: null };
  const vcpu = Math.max(1, Math.floor(planVcpu || 1));
  if (facts.poolThreads === null || !(facts.poolThreads >= 0)) {
    // A node with reservations whose pool we cannot size must not take VMs —
    // fail closed. Unknown topology elsewhere = CPU-neutral (RAM decides).
    return facts.hasReservations
      ? { projectedPct: null, budgetVcpu: null, refused: true, reason: "CPU topology unknown on a node with CPU reservations" }
      : { projectedPct: null, budgetVcpu: null, refused: false, reason: null };
  }
  const budget = facts.poolThreads * ratio;
  const projected = facts.committedVcpu + vcpu;
  const projectedPct = budget > 0 ? (projected / budget) * 100 : Infinity;
  const refused = facts.hasReservations && projected > budget;
  return {
    projectedPct,
    budgetVcpu: budget,
    refused,
    reason: refused
      ? `shared CPU pool full: ${facts.committedVcpu} + ${vcpu} vCPU > ${budget} (${facts.poolThreads} shared thread(s) × ${ratio})`
      : null,
  };
}

export type RankInput<T> = {
  item: T;
  /** Committed RAM % after this VM. */
  ramPct: number;
  /** Free committed RAM (MB) before this VM — the legacy sort key. */
  freeRamMB: number;
  cpu: CpuVerdict;
  hasReservations: boolean;
};

/**
 * Is the candidate "roomy" (under the critical threshold)? RAM always counts;
 * CPU counts only for a node with reservations (its shared pool is genuinely
 * scarce) — see the mode table above.
 */
export function isRoomy(c: RankInput<unknown>, critPct: number, mode: CpuSchedMode): boolean {
  if (c.ramPct >= critPct) return false;
  if (mode !== "off" && c.hasReservations && c.cpu.projectedPct !== null && c.cpu.projectedPct >= critPct) return false;
  return true;
}

/**
 * Order candidates best-first. off/guard: legacy (most free RAM first).
 * score: lowest "worst dimension" first (max of RAM% and CPU%, CPU unknown =
 * RAM only), ties broken by most free RAM.
 */
export function rankCandidates<T>(cands: RankInput<T>[], mode: CpuSchedMode): RankInput<T>[] {
  const out = [...cands];
  if (mode !== "score") return out.sort((a, b) => b.freeRamMB - a.freeRamMB);
  const worst = (c: RankInput<T>) => Math.max(c.ramPct, c.cpu.projectedPct ?? 0);
  return out.sort((a, b) => worst(a) - worst(b) || b.freeRamMB - a.freeRamMB);
}

