  VM_MOVE_CLEANUP
}
"""
assert s.count(old)==1
s=s.replace(old,"""  VM_MOVE
  VM_MOVE_CLEANUP
  // Exclusive CPU reservations (lib/cpu-reservation.ts, worker/cpu-affinity.ts):
  // apply / release a reservation, re-sync a node's VM affinities, or re-read a
  // node's CPU topology. `payload.op` discriminates. Server-scoped when it is a
  // reservation change (serialised with that server's other jobs), else null.
  CPU_AFFINITY
}
""")
# Server relation
old="""  telemetryTokenHash            String?                 @unique
  telemetryEvents               TelemetryEvent[]
}
"""
assert s.count(old)==1
s=s.replace(old,"""  telemetryTokenHash            String?                 @unique
  telemetryEvents               TelemetryEvent[]
  // Exclusive CPU reservation (admin-only, lib/actions-cpu-reservation.ts). Null
  // for every server that shares its node's CPUs normally.
  cpuReservation                CpuReservation?
}
""")
# Node fields
old="""  acceptsProvisions Boolean @default(true)
}
"""
assert s.count(old)==1
s=s.replace(old,"""  acceptsProvisions Boolean @default(true)

  // ---- Exclusive CPU reservations (2026-10-06, lib/cpu-reservation.ts) ----
  // The node's REAL CPU topology (lib/cpu-reservation.ts CpuTopology: every
  // thread with its physical core / socket / SMT siblings), read from /sys by
  // the node agent (v5+) or, on the primary, by the worker itself; a node whose
  // agent predates v5 gets a thread count only (source "pve"), which is enough
  // for CPU-aware scheduling but not for a reservation. Refreshed by the
  // cpu-affinity sweep. Null until first read. The shared pool is NOT stored —
  // it is always derived (topology minus the node's CpuReservation rows) so it
  // can never drift from the reservations themselves.
  cpuTopology      Json?
  cpuTopologyAt    DateTime?
