}

/** Validate a POST /v1/vm/affinity body. Returns {vmid, cpuset} (cpuset canonical or null = clear) or {error}. */
function validateAffinityRequest(p, onlineCpus) {
  if (!p || typeof p !== "object" || Array.isArray(p)) return { error: "invalid body" };
  const vmid = p.vmid;
  if (!Number.isInteger(vmid) || vmid < 100 || vmid > 999999999) return { error: "invalid vmid" };
  if (p.cpuset === null) return { vmid, cpuset: null };
  if (typeof p.cpuset !== "string") return { error: "invalid cpuset" };
  const cpus = parseCpuset(p.cpuset);
  if (!cpus || cpus.length === 0) return { error: "invalid cpuset" };
  const online = new Set(onlineCpus || []);
  const bad = cpus.filter((c) => !online.has(c));
  if (bad.length) return { error: `cpu ${formatCpuset(bad)} is not online on this node` };
  return { vmid, cpuset: formatCpuset(cpus) };
}

function execArgv(cmd, args) {
  return new Promise((resolve, reject) => {
    execFile(cmd, args, { timeout: 30_000 }, (err, stdout, stderr) => {
      if (err) return reject(new Error(`${cmd} ${args[0] || ""}: ${String(stderr || err.message).trim().slice(0, 300)}`));
      resolve(String(stdout));
    });
  });
}

/**
 * Set (or clear) one VM's affinity in its config AND on its live threads, then
 * re-read and return the resulting state. `sys` is injectable for tests only.
 */
async function setVmAffinity(vmid, cpuset, sys = {}) {
  const confDir = sys.confDir || QEMU_CONF_DIR;
  const runDir = sys.runDir || QEMU_RUN_DIR;
  const procRoot = sys.procRoot || CPU_PROC_ROOT;
  const exec = sys.exec || execArgv;
  const confPath = path.join(confDir, `${vmid}.conf`);
  if (!fs.existsSync(confPath)) { const e = new Error(`vm ${vmid} has no config on this node`); e.status = 404; throw e; }
  const conf = parseVmConf(fs.readFileSync(confPath, "utf8"));
  if (conf.template) { const e = new Error(`vm ${vmid} is a template`); e.status = 409; throw e; }
  const vmidArg = String(vmid);
  if (cpuset) {
    if (conf.affinity !== cpuset) await exec("qm", ["set", vmidArg, "--affinity", cpuset]);
  } else if (conf.affinity) {
    await exec("qm", ["set", vmidArg, "--delete", "affinity"]);
