//
// Exclusive CPU reservations (lib/cpu-reservation.ts, worker/cpu-affinity.ts):
// the platform's Proxmox API token cannot set a VM's `affinity` option (PVE
// restricts it to root@pam), so this agent — already root on the node — does
// exactly that one thing, narrowly:
//   GET  /v1/cpu/topology        read-only: /sys CPU topology (threads, cores, SMT siblings)
//   GET  /v1/cpu/affinity[?vmid] read-only: every local VM's config affinity + its live
//                                QEMU threads' Cpus_allowed_list
//   POST /v1/vm/affinity {vmid, cpuset|null}
//                                `qm set <vmid> --affinity <set>` (or `--delete affinity`)
//                                and, if the VM is running, `taskset -a -p -c <set> <pid>`
// Inputs are validated strictly (vmid integer with a config on THIS node, never a
// template; cpuset = digits/commas/ranges only, every cpu online here), commands
// run via execFile argv arrays (no shell), and the QEMU pid is proven to belong
// to that vmid (`-id <vmid>` in its cmdline) before taskset touches it. It cannot
// start, stop or change anything else about a VM. The BUSINESS rules (whole
// cores, no overlap, never the last core) live in the worker, which is the only
// caller; this agent only refuses what could never be a valid affinity.
// Parser/formatter mirror lib/cpu-reservation.ts — KEEP IN SYNC (tested).
const CPU_SYS_ROOT = "/sys";
const CPU_PROC_ROOT = "/proc";
const QEMU_CONF_DIR = "/etc/pve/qemu-server";
const QEMU_RUN_DIR = "/var/run/qemu-server";
const CPUSET_RE = /^\d{1,4}(?:-\d{1,4})?(?:,\d{1,4}(?:-\d{1,4})?)*$/;
const MAX_CPU_INDEX = 1023;

function parseCpuset(raw) {
  if (typeof raw !== "string" || raw.length === 0 || raw.length > 512 || !CPUSET_RE.test(raw)) return null;
  const out = new Set();
  for (const part of raw.split(",")) {
    const [a, b] = part.split("-");
    const lo = Number(a);
    const hi = b === undefined ? lo : Number(b);
    if (!Number.isInteger(lo) || !Number.isInteger(hi) || lo > hi || hi > MAX_CPU_INDEX) return null;
    for (let i = lo; i <= hi; i++) out.add(i);
  }
  return [...out].sort((x, y) => x - y);
}
function formatCpuset(cpus) {
  const s = [...new Set(cpus)].filter((n) => Number.isInteger(n) && n >= 0).sort((a, b) => a - b);
  const parts = [];
  for (let i = 0; i < s.length; ) {
    let j = i;
    while (j + 1 < s.length && s[j + 1] === s[j] + 1) j++;
    parts.push(j === i ? String(s[i]) : `${s[i]}-${s[j]}`);
    i = j + 1;
  }
  return parts.join(",");
}
function canonicalCpuset(raw) {
  const c = parseCpuset(raw);
  return c && c.length ? formatCpuset(c) : null;
}

function readTrim(p) {
  try { return fs.readFileSync(p, "utf8").trim(); } catch { return null; }
}

/** /sys CPU topology. `sysRoot`/`procRoot` are injectable for tests only (never from a request). */
function readCpuTopology(sysRoot = CPU_SYS_ROOT, procRoot = CPU_PROC_ROOT) {
  const base = path.join(sysRoot, "devices/system/cpu");
  const online = parseCpuset(readTrim(path.join(base, "online")) || "");
  if (!online || online.length === 0) throw new Error("cannot read online CPUs");
  const threads = online.map((cpu) => {
    const t = path.join(base, `cpu${cpu}`, "topology");
    const core = Number(readTrim(path.join(t, "core_id")));
    const socket = Number(readTrim(path.join(t, "physical_package_id")));
    const sib = canonicalCpuset(readTrim(path.join(t, "thread_siblings_list")) || "") || String(cpu);
    return { cpu, core: Number.isInteger(core) ? core : cpu, socket: Number.isInteger(socket) ? socket : 0, siblings: sib };
  });
  const cpuinfo = readTrim(path.join(procRoot, "cpuinfo")) || "";
  const m = /^model name\s*:\s*(.+)$/m.exec(cpuinfo);
  return { source: "agent", threadCount: threads.length, threads, online: formatCpuset(online), model: m ? m[1].trim().slice(0, 120) : null };
}

/** Parse a qemu-server .conf: the main section, the [PENDING] section and its `delete:` list. Snapshot sections are ignored. */
function parseVmConf(text) {
  const main = {};
  const pending = {};
  let section = "main";
  for (const raw of String(text || "").split("\n")) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const sec = /^\[([^\]]+)\]$/.exec(line);
    if (sec) { section = sec[1] === "PENDING" ? "pending" : "other"; continue; }
    const i = line.indexOf(":");
    if (i <= 0) continue;
    const k = line.slice(0, i).trim();
    const v = line.slice(i + 1).trim();
    if (section === "main") main[k] = v;
    else if (section === "pending") pending[k] = v;
  }
  const pendingDelete = (pending.delete || "").split(/[,;\s]+/).map((x) => x.replace(/^!/, "")).filter(Boolean);
  let affinity = main.affinity || null;
  if (pending.affinity) affinity = pending.affinity;
  else if (pendingDelete.includes("affinity")) affinity = null;
  return { main, pending, pendingDelete, template: main.template === "1", affinity: affinity ? canonicalCpuset(affinity) || affinity : null };
}

/** QEMU pid for vmid, proven by its cmdline (`-id <vmid>`), else null (not running / stale pidfile). */
function qemuPid(vmid, runDir, procRoot) {
  const raw = readTrim(path.join(runDir, `${vmid}.pid`));
  if (!raw || !/^\d{1,9}$/.test(raw)) return null;
  let cmd;
  try { cmd = fs.readFileSync(path.join(procRoot, raw, "cmdline"), "utf8").split("\0"); } catch { return null; }
  for (let i = 0; i < cmd.length - 1; i++) if (cmd[i] === "-id" && cmd[i + 1] === String(vmid)) return Number(raw);
  return null;
}

function liveThreads(pid, procRoot) {
  const out = [];
  let tids = [];
  try { tids = fs.readdirSync(path.join(procRoot, String(pid), "task")); } catch { return out; }
  for (const tid of tids) {
    if (!/^\d+$/.test(tid)) continue;
    const st = readTrim(path.join(procRoot, String(pid), "task", tid, "status")) || "";
    const m = /^Cpus_allowed_list:\s*(\S+)$/m.exec(st);
    if (m) out.push({ tid: Number(tid), cpus: canonicalCpuset(m[1]) || m[1] });
  }
  return out.sort((a, b) => a.tid - b.tid);
}

/** Every local VM's affinity state (or one vmid). Read-only. Dirs injectable for tests only. */
function readVmAffinities(opts = {}) {
  const confDir = opts.confDir || QEMU_CONF_DIR;
  const runDir = opts.runDir || QEMU_RUN_DIR;
  const procRoot = opts.procRoot || CPU_PROC_ROOT;
  let names = [];
  try { names = fs.readdirSync(confDir); } catch (e) { throw new Error(`cannot list ${confDir}: ${e.message}`); }
  const vms = [];
  for (const name of names) {
    const m = /^(\d{1,9})\.conf$/.exec(name);
    if (!m) continue;
    const vmid = Number(m[1]);
    if (opts.vmid !== undefined && opts.vmid !== null && vmid !== opts.vmid) continue;
    const conf = parseVmConf(readTrim(path.join(confDir, name)) || "");
    const pid = conf.template ? null : qemuPid(vmid, runDir, procRoot);
    vms.push({ vmid, template: conf.template, running: pid !== null, configAffinity: conf.affinity, threads: pid !== null ? liveThreads(pid, procRoot) : [] });
  }
  return vms.sort((a, b) => a.vmid - b.vmid);
}

/** Validate a POST /v1/vm/affinity body. Returns {vmid, cpuset} (cpuset canonical or null = clear) or {error}. */
function validateAffinityRequest(p, onlineCpus) {
  if (!p || typeof p !== "object" || Array.isArray(p)) return { error: "invalid body" };
  const vmid = p.vmid;
  if (!Number.isInteger(vmid) || vmid < 100 || vmid > 999999999) return { error: "invalid vmid" };
  if (p.cpuset === null) return { vmid, cpuset: null };
  if (typeof p.cpuset !== "string") return { error: "invalid cpuset" };
  const cpus = parseCpuset(p.cpuset);
  if (!cpus || cpus.length === 0) return { error: "invalid cpuset" };
  const online = new Set(onlineCpus || []);
  const bad = cpus.filter((c) => !online.has(c));
  if (bad.length) return { error: `cpu ${formatCpuset(bad)} is not online on this node` };
  return { vmid, cpuset: formatCpuset(cpus) };
}

function execArgv(cmd, args) {
  return new Promise((resolve, reject) => {
    execFile(cmd, args, { timeout: 30_000 }, (err, stdout, stderr) => {
      if (err) return reject(new Error(`${cmd} ${args[0] || ""}: ${String(stderr || err.message).trim().slice(0, 300)}`));
      resolve(String(stdout));
    });
  });
}

/**
 * Set (or clear) one VM's affinity in its config AND on its live threads, then
 * re-read and return the resulting state. `sys` is injectable for tests only.
 */
async function setVmAffinity(vmid, cpuset, sys = {}) {
  const confDir = sys.confDir || QEMU_CONF_DIR;
  const runDir = sys.runDir || QEMU_RUN_DIR;
  const procRoot = sys.procRoot || CPU_PROC_ROOT;
  const exec = sys.exec || execArgv;
  const confPath = path.join(confDir, `${vmid}.conf`);
  if (!fs.existsSync(confPath)) { const e = new Error(`vm ${vmid} has no config on this node`); e.status = 404; throw e; }
  const conf = parseVmConf(fs.readFileSync(confPath, "utf8"));
  if (conf.template) { const e = new Error(`vm ${vmid} is a template`); e.status = 409; throw e; }
  const vmidArg = String(vmid);
  if (cpuset) {
    if (conf.affinity !== cpuset) await exec("qm", ["set", vmidArg, "--affinity", cpuset]);
  } else if (conf.affinity) {
    await exec("qm", ["set", vmidArg, "--delete", "affinity"]);
  }
  const pid = qemuPid(vmid, runDir, procRoot);
  if (pid !== null) {
    const want = cpuset || formatCpuset(sys.onlineCpus || readCpuTopology(sys.sysRoot, procRoot).threads.map((t) => t.cpu));
    const threads = liveThreads(pid, procRoot);
    if (threads.some((t) => t.cpus !== want)) await exec("taskset", ["-a", "-p", "-c", want, String(pid)]);
  }
  return readVmAffinities({ confDir, runDir, procRoot, vmid })[0] || null;
}

