    if (!/^\d{3,9}$/.test(vmidRaw)) return sendJson(res, 400, { error: "invalid vmid" });
    vmid = Number(vmidRaw);
  }
  sendJson(res, 200, { vms: readVmAffinities({ vmid }) });
}

