  const p = parseJson(rawBody);
  let online;
  try { online = readCpuTopology().threads.map((t) => t.cpu); } catch (e) { return sendJson(res, 500, { error: e.message }); }
  const v = validateAffinityRequest(p, online);
  if (v.error) return sendJson(res, 400, { error: v.error });
  try {
    const vm = await setVmAffinity(v.vmid, v.cpuset, { onlineCpus: online });
    sendJson(res, 200, { ok: true, vm });
  } catch (e) {
