/**
 * Exclusive CPU reservations — the worker half (applies + enforces what
 * lib/cpu-reservation.ts decides). See that file's header for the why.
 *
 *   ensureVmAffinityBeforeStart  called by EVERY path that creates or recreates
 *                                a VM's config (provision/reinstall, backup
 *                                restore, snapshot rollback, resize, VM move
 *                                target/rollback start) right BEFORE the start:
 *                                on a node with reservations the VM is confined
 *                                (its reservation, or the shared pool) before it
 *                                ever runs — no window on reserved cores. FAILS
 *                                CLOSED there: if it cannot be confined, the VM
 *                                is not started (the job errors/retries).
 *   cpuAffinitySweep             every minute: on every node with reservations,
 *                                compare desired vs actual (config AND every
 *                                live QEMU thread) for every non-template VM,
 *                                fix drift, alert admins when a reservation's
 *                                cores were found reachable by another VM.
 *                                Also refreshes Node.cpuTopology (6-hourly).
 *   cpuAffinityJob               CPU_AFFINITY job: apply/release a reservation
 *                                (admin action), re-sync a node, read topology.
 *
 * WHO SETS AFFINITY: the platform's Proxmox API token cannot (PVE returns 500 —
 * root@pam only). Non-primary nodes: the node agent v5's POST /v1/vm/affinity.
 * Primary (no agent; this worker runs there as root): the SAME code, loaded
 * from node-agent/index.js and run locally (`qm set` + `taskset`).
 */
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { pveFor } from "../lib/proxmox";
import { agentCpuAffinity, agentCpuTopology, agentSetVmAffinity, isAgentTooOld, type AgentNode } from "../lib/node-agent";
import {
  affinityDrift,
  allThreads,
  desiredAffinity,
  findSharing,
  sameCpuset,
  validateReservation,
  type CpuTopology,
  type VmAffinityState,
} from "../lib/cpu-reservation";
import { notifyAdmins } from "./monitor";
// Plain CJS, dependency-free; exports its pure + system helpers when require()d.
import agentLib from "../node-agent/index.js";
import type { Job, Prisma } from "@prisma/client";

const TOPOLOGY_MAX_AGE_MS = 6 * 60 * 60_000;

export type CpuNode = AgentNode & {
  isPrimary: boolean;
  pveNode: string;
  apiUrl: string;
  tokenId: string;
  tokenSecret: string;
  cpuTopology: Prisma.JsonValue | null;
  cpuTopologyAt: Date | null;
};

const CPU_NODE_SELECT = {
  id: true, name: true, isPrimary: true, publicIp: true, agentPort: true, agentTokenEnc: true,
  pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true, cpuTopology: true, cpuTopologyAt: true,
} as const;

export interface CpuHost {
  kind: "local" | "agent";
  topology(): Promise<CpuTopology>;
  list(vmid?: number): Promise<VmAffinityState[]>;
  set(vmid: number, cpuset: string | null): Promise<VmAffinityState | null>;
}

const lib = agentLib as unknown as {
  readCpuTopology(): CpuTopology;
  readVmAffinities(o?: { vmid?: number | null }): VmAffinityState[];
  setVmAffinity(vmid: number, cpuset: string | null, sys?: Record<string, unknown>): Promise<VmAffinityState | null>;
  validateAffinityRequest(p: unknown, online: number[]): { vmid?: number; cpuset?: string | null; error?: string };
};

/** The primary: same validation + apply code the agent runs, executed in this (root) process. */
function localHost(): CpuHost {
  return {
    kind: "local",
    async topology() {
      return { ...lib.readCpuTopology(), source: "local" };
    },
    async list(vmid) {
      return lib.readVmAffinities({ vmid: vmid ?? null });
    },
    async set(vmid, cpuset) {
      const online = lib.readCpuTopology().threads.map((t) => t.cpu);
      const v = lib.validateAffinityRequest({ vmid, cpuset }, online);
      if (v.error) throw new Error(`refused: ${v.error}`);
      return lib.setVmAffinity(v.vmid!, v.cpuset ?? null, { onlineCpus: online });
    },
  };
}

function agentHost(node: AgentNode): CpuHost {
  return {
    kind: "agent",
    topology: () => agentCpuTopology(node),
    list: (vmid) => agentCpuAffinity(node, vmid),
    set: (vmid, cpuset) => agentSetVmAffinity(node, vmid, cpuset),
  };
}

export function cpuHostFor(node: Pick<CpuNode, "isPrimary"> & AgentNode): CpuHost {
  return node.isPrimary ? localHost() : agentHost(node);
}

export function topologyOf(node: { cpuTopology: Prisma.JsonValue | null }): CpuTopology | null {
  const t = node.cpuTopology as unknown as CpuTopology | null;
  return t && typeof t === "object" && typeof t.threadCount === "number" ? t : null;
}

/** Reservations on a node, each resolved to its server's current vmid. */
export async function nodeReservations(nodeId: string) {
  const rows = await db.cpuReservation.findMany({
    where: { nodeId },
    include: { server: { select: { vmid: true, hostname: true, nodeId: true } } },
    orderBy: { createdAt: "asc" },
  });
  return rows.map((r) => ({
    id: r.id,
    serverId: r.serverId,
    cpuset: r.cpuset,
    label: r.server.hostname,
    // A reservation whose server has moved to another node still HOLDS these
    // cores here (see the model's doc), but there is no owner VM on this node.
    vmid: r.server.nodeId === nodeId ? r.server.vmid : null,
  }));
}

async function loadCpuNode(nodeId: string): Promise<CpuNode | null> {
  return db.node.findUnique({ where: { id: nodeId }, select: CPU_NODE_SELECT }) as Promise<CpuNode | null>;
}

/**
 * Confine `vmid` on `nodeId` to its desired cpuset before it is started.
 * - Node has reservations → set it (reservation or shared pool) and VERIFY by
 *   re-reading; any failure THROWS so the caller never starts the VM.
 * - Node has none → if the VM carries a leftover affinity (e.g. restored from
 *   an archive of a reserved VM) clear it, best-effort; never blocks.
 */
export async function ensureVmAffinityBeforeStart(args: { nodeId: string | null | undefined; vmid: number; why: string }): Promise<{ cpuset: string | null; reason: string }> {
  if (SANDBOX || !args.nodeId) return { cpuset: null, reason: "unmanaged" };
  const node = await loadCpuNode(args.nodeId);
  if (!node) return { cpuset: null, reason: "unmanaged" };
  const reservations = await nodeReservations(node.id);
  const host = cpuHostFor(node);
  if (reservations.length === 0) {
    try {
      const [st] = await host.list(args.vmid);
      if (st?.configAffinity) {
        await host.set(args.vmid, null);
        console.log(`[cpu-affinity] ${args.why}: cleared leftover affinity ${st.configAffinity} on vm ${args.vmid} (${node.name} has no reservations)`);
      }
    } catch (e) {
      if (!isAgentTooOld(e)) console.warn(`[cpu-affinity] ${args.why}: could not check vm ${args.vmid} for a leftover affinity on ${node.name}: ${(e as Error)?.message ?? e}`);
    }
    return { cpuset: null, reason: "unmanaged" };
  }
  const want = desiredAffinity({ vmid: args.vmid, topology: topologyOf(node), reservations });
  let after: VmAffinityState | null;
  try {
    after = await host.set(args.vmid, want.cpuset);
  } catch (e) {
    throw new Error(
      `CPU reservation guard: could not confine VM ${args.vmid} on ${node.name} to CPUs ${want.cpuset} (${want.reason}) — ` +
        `the VM was NOT started so it cannot run on another customer's dedicated cores. ${isAgentTooOld(e) ? "The node agent is older than v5; upgrade it. " : ""}` +
        `${String((e as Error)?.message ?? e).slice(0, 240)}`,
    );
  }
  if (!after || !sameCpuset(after.configAffinity, want.cpuset) || after.threads.some((t) => !sameCpuset(t.cpus, want.cpuset))) {
    throw new Error(`CPU reservation guard: VM ${args.vmid} on ${node.name} reads back affinity ${after?.configAffinity ?? "none"} instead of ${want.cpuset} — not starting it.`);
  }
  console.log(`[cpu-affinity] ${args.why}: vm ${args.vmid} on ${node.name} confined to ${want.cpuset} (${want.reason})`);
  return want;
}

// ---------------------------------------------------------------------------
// Topology
// ---------------------------------------------------------------------------

/** Read + persist a node's topology. Falls back to a thread COUNT from the Proxmox API when the agent predates v5. */
export async function refreshTopology(node: CpuNode, opts: { force?: boolean } = {}): Promise<CpuTopology | null> {
  const fresh = node.cpuTopologyAt && Date.now() - node.cpuTopologyAt.getTime() < TOPOLOGY_MAX_AGE_MS;
  const current = topologyOf(node);
  if (!opts.force && fresh && current) return current;
  let topo: CpuTopology | null = null;
  try {
    topo = await cpuHostFor(node).topology();
  } catch (e) {
    if (!isAgentTooOld(e) && !/no agent token/.test(String((e as Error)?.message))) throw e;
    // Keep a previously-read full map (it does not change); otherwise thread count only.
    if (current?.threads?.length) return current;
    const st = await pveFor(node).get(`/nodes/${node.pveNode}/status`).catch(() => null);
    const cpus = Number(st?.cpuinfo?.cpus);
    if (Number.isInteger(cpus) && cpus > 0) topo = { source: "pve", threadCount: cpus, threads: [], model: st?.cpuinfo?.model ?? null };
  }
  if (!topo) return current;
  await db.node.update({ where: { id: node.id }, data: { cpuTopology: topo as unknown as Prisma.InputJsonValue, cpuTopologyAt: new Date() } });
  node.cpuTopology = topo as unknown as Prisma.JsonValue;
  node.cpuTopologyAt = new Date();
  return topo;
}

// ---------------------------------------------------------------------------
// Node sync (sweep + job)
// ---------------------------------------------------------------------------

export type NodeSyncResult = {
  node: string;
  reservations: number;
  vms: number;
  fixed: { vmid: number; from: string | null; to: string | null; live: boolean }[];
  sharingBefore: { reservation: string; offenders: { vmid: number; where: string; cpus: string }[] }[];
  sharingAfter: { reservation: string; offenders: { vmid: number; where: string; cpus: string }[] }[];
  errors: string[];
};

/**
 * Bring every non-template VM on the node to its desired affinity. With no
 * reservations left (`releaseAll`), clears every VM's affinity instead — used
 * by the release job when the node's last reservation goes away.
 */
export async function syncNode(node: CpuNode, opts: { releaseAll?: boolean; why: string }): Promise<NodeSyncResult> {
  const reservations = await nodeReservations(node.id);
  const out: NodeSyncResult = { node: node.name, reservations: reservations.length, vms: 0, fixed: [], sharingBefore: [], sharingAfter: [], errors: [] };
  if (reservations.length === 0 && !opts.releaseAll) return out;
  const host = cpuHostFor(node);
  const topo = reservations.length ? await refreshTopology(node) : topologyOf(node);
  const threads = allThreads(topo);
  const before = await host.list();
  out.vms = before.length;
  const label = (s: ReturnType<typeof findSharing>) =>
    s.map((x) => ({ reservation: x.reservation.label ?? x.reservation.serverId, offenders: x.offenders }));
  out.sharingBefore = label(findSharing(reservations, before, threads));

  for (const vm of before) {
    if (vm.template) continue;
    let want: string | null;
    try {
      want = reservations.length ? desiredAffinity({ vmid: vm.vmid, topology: topo, reservations }).cpuset : null;
    } catch (e) {
      out.errors.push(String((e as Error).message));
      continue;
    }
    const d = affinityDrift(want, vm);
    const liveAll = want === null && vm.running && vm.threads.some((t) => !sameCpuset(t.cpus, threads.length ? threads.join(",") : t.cpus));
    if (d.configOk && d.badThreads.length === 0 && !(opts.releaseAll && liveAll)) continue;
    try {
      await host.set(vm.vmid, want);
      out.fixed.push({ vmid: vm.vmid, from: vm.configAffinity, to: want, live: d.badThreads.length > 0 });
      console.log(`[cpu-affinity] ${opts.why}: ${node.name} vm ${vm.vmid} ${vm.configAffinity ?? "unset"} -> ${want ?? "unset"}${d.badThreads.length ? ` (${d.badThreads.length} live thread(s) re-pinned)` : ""}`);
    } catch (e) {
      out.errors.push(`vm ${vm.vmid}: ${String((e as Error)?.message ?? e).slice(0, 200)}`);
    }
  }

  if (reservations.length) {
    const after = out.fixed.length ? await host.list() : before;
    out.sharingAfter = label(findSharing(reservations, after, threads));
    const now = new Date();
    for (const r of reservations) {
      const own = r.vmid !== null ? after.find((v) => v.vmid === r.vmid) : undefined;
      const ownOk = !own || affinityDrift(r.cpuset, own).configOk && affinityDrift(r.cpuset, own).badThreads.length === 0;
      const shared = out.sharingAfter.find((s) => s.reservation === (r.label ?? r.serverId));
      const hadDrift = out.sharingBefore.find((s) => s.reservation === (r.label ?? r.serverId)) || out.fixed.some((f) => f.vmid === r.vmid);
      await db.cpuReservation.update({
        where: { id: r.id },
        data: {
          ...(ownOk && !shared && out.errors.length === 0 ? { lastVerifiedAt: now } : {}),
          ...(hadDrift || shared
            ? { lastDriftAt: now, lastDriftDetail: JSON.stringify({ before: out.sharingBefore, after: out.sharingAfter, fixed: out.fixed }).slice(0, 2000) }
            : {}),
        },
      }).catch(() => {});
    }
  }
  return out;
}

async function alertForSync(node: CpuNode, r: NodeSyncResult): Promise<void> {
  for (const s of r.sharingBefore) {
    const still = r.sharingAfter.find((a) => a.reservation === s.reservation);
    const list = s.offenders.map((o) => `VM ${o.vmid} (${o.where}: ${o.cpus})`).join(", ");
    await notifyAdmins(
      still ? `CPU reservation BREACHED on ${node.name}: ${s.reservation}` : `CPU reservation drift fixed on ${node.name}: ${s.reservation}`,
      still
        ? `Another VM can still run on ${s.reservation}'s dedicated cores and the automatic fix did not take: ${list}. Errors: ${r.errors.join("; ") || "none"}. Check the node agent and the node's VM configs now.`
        : `Found other VM(s) able to run on ${s.reservation}'s dedicated cores and confined them back to the shared pool: ${list}. Someone or something changed a VM's affinity outside the platform (manual qm set, restore, rollback) — worth checking who.`,
      `/admin/nodes/${node.id}`,
    ).catch(() => {});
  }
}

/** Every minute. Nodes without reservations only get a (6-hourly) topology refresh. */
export async function cpuAffinitySweep(): Promise<void> {
  if (SANDBOX) return;
  const nodes = (await db.node.findMany({ where: { enabled: true }, select: CPU_NODE_SELECT })) as CpuNode[];
  const reservedNodeIds = new Set((await db.cpuReservation.findMany({ select: { nodeId: true }, distinct: ["nodeId"] })).map((r) => r.nodeId));
  for (const node of nodes) {
    if (!reservedNodeIds.has(node.id)) {
      await refreshTopology(node).catch(() => undefined);
      continue;
    }
    try {
      const r = await syncNode(node, { why: "sweep" });
      await alertForSync(node, r);
      if (r.errors.length) console.error(`[cpu-affinity] sweep ${node.name}: ${r.errors.join("; ")}`);
    } catch (e) {
      const msg = String((e as Error)?.message ?? e).slice(0, 300);
      console.error(`[cpu-affinity] sweep ${node.name} failed: ${msg}`);
      await notifyAdmins(
        `CPU reservations NOT being enforced on ${node.name}`,
        `The cpu-affinity sweep could not read or fix VM CPU affinity on ${node.name}: ${msg}. ${isAgentTooOld(e) ? "The node agent is older than v5 — upgrade it (docs: CPU reservations rollout). " : ""}Dedicated cores may be exposed to other VMs until this is fixed.`,
        `/admin/nodes/${node.id}`,
      ).catch(() => {});
    }
  }
}

// ---------------------------------------------------------------------------
// CPU_AFFINITY job
// ---------------------------------------------------------------------------

export type CpuAffinityJobPayload = {
  op: "apply" | "release" | "sync-node" | "refresh-topology";
  nodeId: string;
  reservationId?: string;
  requestedBy?: string;
  result?: unknown;
};

export async function cpuAffinityJob(job: Job): Promise<void> {
  const p = (job.payload ?? {}) as CpuAffinityJobPayload;
  const node = p.nodeId ? await loadCpuNode(p.nodeId) : null;
  if (!node) throw new Error("CPU_AFFINITY: node not found");
  if (SANDBOX) {
    await saveResult(job, p, { sandbox: true });
    return;
  }
  let result: unknown;
  if (p.op === "refresh-topology") {
    result = await refreshTopology(node, { force: true });
  } else if (p.op === "apply") {
    const r = p.reservationId ? await db.cpuReservation.findUnique({ where: { id: p.reservationId }, include: { server: { select: { gamePlan: { select: { cpuCores: true } }, plan: { select: { cpuCores: true } } } } } }) : null;
    if (!r) throw new Error("CPU_AFFINITY apply: reservation no longer exists (released?)");
    // Re-validate against the LIVE topology, not the cached one the admin page used.
    const topo = await refreshTopology(node, { force: true });
    const others = (await nodeReservations(node.id)).filter((o) => o.id !== r.id);
    const check = validateReservation({ topology: topo, cpuset: r.cpuset, others, vcpu: r.server.gamePlan?.cpuCores ?? r.server.plan.cpuCores });
    if (!check.ok) throw new Error(`reservation ${r.cpuset} is not valid against ${node.name}'s live topology: ${check.errors.join(" ")}`);
    result = await syncNode(node, { why: `apply reservation ${r.id}` });
  } else if (p.op === "release") {
    const left = await db.cpuReservation.count({ where: { nodeId: node.id } });
    result = await syncNode(node, { why: "release reservation", releaseAll: left === 0 });
  } else if (p.op === "sync-node") {
    result = await syncNode(node, { why: "manual re-sync" });
  } else {
    throw new Error(`CPU_AFFINITY: unknown op ${String(p.op)}`);
  }
  await saveResult(job, p, result);
  await db.auditLog.create({
    data: { userId: p.requestedBy ?? null, action: `cpu_reservation.job_${p.op}`, detail: `node=${node.name} ${JSON.stringify(result).slice(0, 1500)}` },
  }).catch(() => {});
  const r = result as NodeSyncResult | null;
  if (r && Array.isArray(r.sharingAfter) && r.sharingAfter.length) {
    await alertForSync(node, r);
    throw new Error(`reservation still shared after sync on ${node.name}: ${JSON.stringify(r.sharingAfter).slice(0, 300)}`);
  }
  if (r && Array.isArray(r.errors) && r.errors.length) throw new Error(`sync on ${node.name} had errors: ${r.errors.join("; ").slice(0, 400)}`);
}

async function saveResult(job: Job, p: CpuAffinityJobPayload, result: unknown): Promise<void> {
  await db.job.update({ where: { id: job.id }, data: { payload: { ...p, result } as unknown as Prisma.InputJsonValue } }).catch(() => {});
}

