/**
 * Exclusive CPU reservations — the worker half (applies + enforces what
 * lib/cpu-reservation.ts decides). See that file's header for the why.
 *
 *   ensureVmAffinityBeforeStart  called by EVERY path that creates or recreates
 *                                a VM's config (provision/reinstall, backup
 *                                restore, snapshot rollback, resize, VM move
 *                                target/rollback start) right BEFORE the start:
 *                                on a node with reservations the VM is confined
 *                                (its reservation, or the shared pool) before it
 *                                ever runs — no window on reserved cores. FAILS
 *                                CLOSED there: if it cannot be confined, the VM
 *                                is not started (the job errors/retries).
 *   cpuAffinitySweep             every minute: on every node with reservations,
 *                                compare desired vs actual (config AND every
 *                                live QEMU thread) for every non-template VM,
 *                                fix drift, alert admins when a reservation's
 *                                cores were found reachable by another VM.
 *                                Also refreshes Node.cpuTopology (6-hourly).
 *   cpuAffinityJob               CPU_AFFINITY job: apply/release a reservation
 *                                (admin action), re-sync a node, read topology.
 *
 * WHO SETS AFFINITY: the platform's Proxmox API token cannot (PVE returns 500 —
 * root@pam only). Non-primary nodes: the node agent v5's POST /v1/vm/affinity.
 * Primary (no agent; this worker runs there as root): the SAME code, loaded
 * from node-agent/index.js and run locally (`qm set` + `taskset`).
 */
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { pveFor } from "../lib/proxmox";
import { agentCpuAffinity, agentCpuTopology, agentSetVmAffinity, isAgentTooOld, type AgentNode } from "../lib/node-agent";
import {
  affinityDrift,
  allThreads,
  desiredAffinity,
  findSharing,
  sameCpuset,
  validateReservation,
  type CpuTopology,
  type VmAffinityState,
} from "../lib/cpu-reservation";
import { notifyAdmins } from "./monitor";
// Plain CJS, dependency-free; exports its pure + system helpers when require()d.
import agentLib from "../node-agent/index.js";
import type { Job, Prisma } from "@prisma/client";

const TOPOLOGY_MAX_AGE_MS = 6 * 60 * 60_000;

export type CpuNode = AgentNode & {
  isPrimary: boolean;
  pveNode: string;
  apiUrl: string;
  tokenId: string;
  tokenSecret: string;
  cpuTopology: Prisma.JsonValue | null;
  cpuTopologyAt: Date | null;
};

const CPU_NODE_SELECT = {
  id: true, name: true, isPrimary: true, publicIp: true, agentPort: true, agentTokenEnc: true,
  pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true, cpuTopology: true, cpuTopologyAt: true,
} as const;

export interface CpuHost {
  kind: "local" | "agent";
  topology(): Promise<CpuTopology>;
  list(vmid?: number): Promise<VmAffinityState[]>;
  set(vmid: number, cpuset: string | null): Promise<VmAffinityState | null>;
}

const lib = agentLib as unknown as {
  readCpuTopology(): CpuTopology;
