  };
}

function agentHost(node: AgentNode): CpuHost {
  return {
    kind: "agent",
    topology: () => agentCpuTopology(node),
    list: (vmid) => agentCpuAffinity(node, vmid),
    set: (vmid, cpuset) => agentSetVmAffinity(node, vmid, cpuset),
  };
}

