 * shared pool when the node has CPU reservations) and vCPU already committed
 * to that pool (every live server on the node except reservation owners).
 */
export function nodeCpuFacts(
  node: { id: string; cpuTopology: unknown },
  servers: { id: string; vcpu: number }[],
  reservations: { serverId: string; cpuset: string }[],
): { poolThreads: number | null; committedVcpu: number; hasReservations: boolean; totalThreads: number | null; reservedServerIds: Set<string> } {
  const topo = (node.cpuTopology ?? null) as CpuTopology | null;
  const hasReservations = reservations.length > 0;
  const reservedServerIds = new Set(reservations.map((r) => r.serverId));
