"use server";

/**
 * Exclusive CPU reservations — admin server actions (lib/cpu-reservation.ts for
 * the rules, worker/cpu-affinity.ts for how they are applied). Every export
 * requires the "fleet" area, is audited, and only writes the DB + enqueues a
 * CPU_AFFINITY job: the web app never touches a node (the worker does, through
 * the node agent / its own root path on the primary).
 *
 * Concurrency: reservation writes for one node are serialised by a
 * transaction-scoped advisory lock keyed on the node id, so two admins cannot
 * both pass the overlap check and reserve the same cores.
 */
import { z } from "zod";
import { revalidatePath } from "next/cache";
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { recordAudit } from "@/lib/audit";
import { validateReservation, type CpuTopology } from "@/lib/cpu-reservation";

const NODE_LOCK_NAMESPACE = 7302;
const NODE_LOCK_SQL = `SELECT 1 AS locked FROM (SELECT pg_advisory_xact_lock(${NODE_LOCK_NAMESPACE}, hashtext($1))) _lock`;

const idSchema = z.string().min(5).max(64).regex(/^[a-z0-9-]+$/i);

export type CpuReservationResult = { ok: true; jobId: string; warnings: string[] } | { ok: false; error: string };

/** Create or replace a server's reservation on the node it currently lives on. */
export async function setCpuReservation(input: { serverId: string; cpuset: string; note?: string }): Promise<CpuReservationResult> {
  const admin = await requireArea("fleet");
  const parsed = z.object({ serverId: idSchema, cpuset: z.string().min(1).max(200), note: z.string().max(500).optional() }).safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid request." };
  const { serverId, cpuset, note } = parsed.data;

  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, hostname: true, vmid: true, nodeId: true, status: true, plan: { select: { cpuCores: true } }, gamePlan: { select: { cpuCores: true } } },
  });
  if (!server) return { ok: false, error: "Server not found." };
  if (!server.nodeId) return { ok: false, error: "This server has no node assigned; it cannot hold a CPU reservation." };
  if (server.status === "DELETING") return { ok: false, error: "This server is being deleted." };
  const nodeId = server.nodeId;

  const out = await db.$transaction(async (tx) => {
    await tx.$queryRawUnsafe(NODE_LOCK_SQL, nodeId);
    const node = await tx.node.findUnique({ where: { id: nodeId }, select: { id: true, name: true, cpuTopology: true } });
    if (!node) return { ok: false as const, error: "Node not found." };
    const existing = await tx.cpuReservation.findUnique({ where: { serverId } });
    const others = await tx.cpuReservation.findMany({
      where: { nodeId, NOT: { serverId } },
      select: { serverId: true, cpuset: true, server: { select: { hostname: true } } },
    });
    const check = validateReservation({
      topology: node.cpuTopology as unknown as CpuTopology | null,
      cpuset,
      others: others.map((o) => ({ serverId: o.serverId, cpuset: o.cpuset, label: o.server.hostname })),
      vcpu: server.gamePlan?.cpuCores ?? server.plan.cpuCores,
    });
    if (!check.ok || !check.cpuset) return { ok: false as const, error: check.errors.join(" ") };
    const inflight = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: "CPU_AFFINITY" } });
    if (inflight > 0) return { ok: false as const, error: "A CPU reservation change for this server is already in progress." };
    const row = existing
      ? await tx.cpuReservation.update({ where: { id: existing.id }, data: { nodeId, cpuset: check.cpuset, note: note ?? existing.note, lastVerifiedAt: null } })
      : await tx.cpuReservation.create({ data: { serverId, nodeId, cpuset: check.cpuset, note: note ?? null, createdById: admin.id } });
    const job = await tx.job.create({
      data: { type: "CPU_AFFINITY", serverId, payload: { op: "apply", nodeId, reservationId: row.id, requestedBy: admin.id } as Prisma.InputJsonValue },
      select: { id: true },
    });
    // Moved from another node: free the cores it held there too.
    if (existing && existing.nodeId !== nodeId) {
