"use client";

/**
 * Admin controls for exclusive CPU reservations (lib/cpu-reservation.ts).
 * - CpuReservationControl: server Compute tab — pick whole physical cores from
 *   the node's real topology, see conflicts live, apply / release.
 * - NodeCpuJobButtons: node page — re-read topology / re-sync VM affinities now.
 * Validation shown here is the SAME pure function the server action and the
 * worker re-run; this view is only a preview.
 */
import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { formatCpuset, parseCpuset, validateReservation, type CpuTopology, type PhysicalCore, physicalCores } from "@/lib/cpu-reservation";
import { setCpuReservation, releaseCpuReservation, requestNodeCpuJob } from "@/lib/actions-cpu-reservation";

export type OtherReservation = { serverId: string; cpuset: string; label: string };

export function CpuReservationControl(props: {
  serverId: string;
  nodeName: string | null;
  topology: CpuTopology | null;
  others: OtherReservation[];
  vcpu: number;
  current: { cpuset: string; nodeName: string; onThisNode: boolean } | null;
  busy: boolean;
}) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ tone: "ok" | "bad"; text: string } | null>(null);
  const cores: PhysicalCore[] = useMemo(() => physicalCores(props.topology), [props.topology]);
  const initial = props.current?.onThisNode ? parseCpuset(props.current.cpuset) ?? [] : [];
  const [picked, setPicked] = useState<Set<string>>(() => new Set(cores.filter((c) => c.threads.every((t) => initial.includes(t))).map((c) => c.key)));
  const [note, setNote] = useState("");

  const takenBy = new Map<number, string>();
  for (const o of props.others) for (const c of parseCpuset(o.cpuset) ?? []) takenBy.set(c, o.label);
  const cpus = cores.filter((c) => picked.has(c.key)).flatMap((c) => c.threads);
  const cpuset = cpus.length ? formatCpuset(cpus) : "";
  const check = cpuset ? validateReservation({ topology: props.topology, cpuset, others: props.others, vcpu: props.vcpu }) : null;
  const unchanged = props.current?.onThisNode && props.current.cpuset === cpuset;

  if (!props.nodeName) return <p className="text-sm text-slate-500">This server has no node, so it cannot hold a CPU reservation.</p>;
  if (cores.length === 0) {
    return (
      <p className="text-sm text-slate-400">
        {props.nodeName}&apos;s CPU topology has not been read yet (node agent v5 needed). Use <span className="font-mono">Read topology</span> on the node page first.
      </p>
    );
  }

  const apply = () =>
    start(async () => {
      setMsg(null);
      const r = await setCpuReservation({ serverId: props.serverId, cpuset, note: note || undefined });
      setMsg(r.ok ? { tone: "ok", text: `Queued (job ${r.jobId}). Other VMs on ${props.nodeName} are moved to the shared pool before this is marked verified.${r.warnings.length ? " " + r.warnings.join(" ") : ""}` } : { tone: "bad", text: r.error });
      router.refresh();
    });
  const release = () =>
    start(async () => {
      if (!confirm("Release this server's dedicated cores? They go back to the node's shared pool and other VMs may run on them.")) return;
      setMsg(null);
      const r = await releaseCpuReservation({ serverId: props.serverId });
      setMsg(r.ok ? { tone: "ok", text: `Released (job ${r.jobId}).` } : { tone: "bad", text: r.error });
      router.refresh();
    });

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-2" role="group" aria-label={`Physical cores on ${props.nodeName}`}>
        {cores.map((c) => {
          const owner = c.threads.map((t) => takenBy.get(t)).find(Boolean);
          const on = picked.has(c.key);
          return (
            <button
              key={c.key}
              type="button"
              disabled={!!owner || pending || props.busy}
              aria-pressed={on}
              onClick={() => setPicked((p) => { const n = new Set(p); if (n.has(c.key)) n.delete(c.key); else n.add(c.key); return n; })}
              className={`rounded-lg border px-3 py-2 text-left text-xs ${on ? "border-brand-400 bg-brand-500/15 text-brand-200" : owner ? "cursor-not-allowed border-white/5 bg-white/[0.02] text-slate-600" : "border-white/10 bg-white/[0.03] text-slate-300 hover:border-white/20"}`}
              title={owner ? `Reserved by ${owner}` : `Threads ${c.key}`}
            >
              <div className="font-semibold">Core {c.socket > 0 ? `${c.socket}:` : ""}{c.core}</div>
              <div className="font-mono">{c.key}</div>
              <div className="mt-0.5">{owner ? owner : on ? "dedicated" : "shared"}</div>
            </button>
          );
        })}
      </div>
      <p className="text-xs text-slate-400">
        Selected: <span className="font-mono">{cpuset || "none"}</span> · VM has {props.vcpu} vCPU
        {props.current && !props.current.onThisNode && <span className="text-amber-300"> · current reservation {props.current.cpuset} is on {props.current.nodeName}, not this server&apos;s node — applying here moves it.</span>}
      </p>
      {check && check.errors.length > 0 && <ul className="list-disc pl-5 text-xs text-red-300">{check.errors.map((e) => <li key={e}>{e}</li>)}</ul>}
      {check && check.warnings.length > 0 && <ul className="list-disc pl-5 text-xs text-amber-300">{check.warnings.map((e) => <li key={e}>{e}</li>)}</ul>}
      <input className="input w-full text-sm" placeholder="Note (e.g. the written promise / ticket this backs)" maxLength={500} value={note} onChange={(e) => setNote(e.target.value)} />
      <div className="flex flex-wrap gap-2">
        <button type="button" className="btn-primary py-1.5 text-xs" disabled={pending || props.busy || !check?.ok || !!unchanged} onClick={apply}>
          {props.current ? "Update reservation" : "Reserve these cores"}
        </button>
        {props.current && (
          <button type="button" className="btn-secondary py-1.5 text-xs" disabled={pending || props.busy} onClick={release}>
            Release reservation
          </button>
        )}
      </div>
      {msg && <p className={`text-xs ${msg.tone === "ok" ? "text-emerald-300" : "text-red-300"}`} role="status">{msg.text}</p>}
    </div>
  );
}

export function NodeCpuJobButtons({ nodeId, canSync }: { nodeId: string; canSync: boolean }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<string | null>(null);
  const run = (op: "refresh-topology" | "sync-node") =>
    start(async () => {
      const r = await requestNodeCpuJob({ nodeId, op });
      setMsg(r.ok ? `Queued job ${r.jobId}.` : r.error);
      router.refresh();
    });
  return (
    <div className="flex flex-wrap items-center gap-2">
      <button type="button" className="btn-secondary py-1.5 text-xs" disabled={pending} onClick={() => run("refresh-topology")}>Read topology</button>
      {canSync && <button type="button" className="btn-secondary py-1.5 text-xs" disabled={pending} onClick={() => run("sync-node")}>Re-sync affinities now</button>}
      {msg && <span className="text-xs text-slate-400" role="status">{msg}</span>}
    </div>
  );
}

