import { test } from "node:test";
import assert from "node:assert/strict";
import { createRequire } from "node:module";
import path from "node:path";
import {
  parseCpuset,
  formatCpuset,
  canonicalCpuset,
  physicalCores,
  validateReservation,
  sharedCpus,
  desiredAffinity,
  affinityDrift,
  findSharing,
  type CpuTopology,
} from "../lib/cpu-reservation";

const agent = createRequire(__filename)(path.resolve(__dirname, "../node-agent/index.js"));

/** node-6: i7-7700K, 4 cores / 8 threads, siblings (0,4) (1,5) (2,6) (3,7). */
const I7: CpuTopology = {
  source: "agent",
  threadCount: 8,
  online: "0-7",
  threads: [0, 1, 2, 3, 4, 5, 6, 7].map((cpu) => ({ cpu, core: cpu % 4, socket: 0, siblings: `${cpu % 4},${(cpu % 4) + 4}` })),
};

test("cpuset: parses and canonicalises ranges", () => {
  assert.deepEqual(parseCpuset("0-2,4-6"), [0, 1, 2, 4, 5, 6]);
  assert.deepEqual(parseCpuset("3,7"), [3, 7]);
  assert.deepEqual(parseCpuset("7,3,3"), [3, 7]);
  assert.equal(formatCpuset([6, 5, 4, 2, 1, 0]), "0-2,4-6");
  assert.equal(formatCpuset([3, 7]), "3,7");
  assert.equal(formatCpuset([3, 4]), "3-4");
  assert.equal(canonicalCpuset("0,1,2,4,5,6"), "0-2,4-6");
});

test("cpuset: rejects anything that is not digits/commas/ascending ranges (injection-safe)", () => {
  for (const bad of ["", " 0", "0 ", "0;rm -rf /", "0,1 && reboot", "$(id)", "-1", "3-1", "1024", "0,,1", "0-", ",0", "0x1", "1e2", "0-2,4-6\n", null, undefined, 5, ["0"], { a: 1 }]) {
    assert.equal(parseCpuset(bad as unknown), null, `should reject ${JSON.stringify(bad)}`);
    assert.equal(agent.parseCpuset(bad), null, `agent should reject ${JSON.stringify(bad)}`);
  }
});

test("cpuset: the node agent's copy agrees with lib/cpu-reservation.ts", () => {
  for (const s of ["0", "0-7", "3,7", "0-2,4-6", "7,6,5,0", "1,2", "0-1,3-4,9", "10-12,1"]) {
    assert.deepEqual(agent.parseCpuset(s), parseCpuset(s), s);
    assert.equal(agent.formatCpuset(parseCpuset(s)), formatCpuset(parseCpuset(s)!), s);
  }
});

test("topology: groups SMT siblings into physical cores", () => {
  const cores = physicalCores(I7);
  assert.deepEqual(cores.map((c) => c.key), ["0,4", "1,5", "2,6", "3,7"]);
  assert.deepEqual(physicalCores({ source: "pve", threadCount: 8, threads: [] }), []);
});

test("validate: syntech-vps's real reservation (3 whole cores) is valid on node-6", () => {
  const r = validateReservation({ topology: I7, cpuset: "0-2,4-6", others: [], vcpu: 6 });
  assert.equal(r.ok, true, r.errors.join(" "));
  assert.equal(r.cpuset, "0-2,4-6");
  assert.equal(r.cores.length, 3);
  assert.deepEqual(r.warnings, []);
  assert.deepEqual(sharedCpus(I7, [{ serverId: "s", cpuset: "0-2,4-6" }]), [3, 7]);
});

test("validate: only whole physical cores (both SMT siblings)", () => {
  const r = validateReservation({ topology: I7, cpuset: "0-2", others: [] });
  assert.equal(r.ok, false);
  assert.match(r.errors.join(" "), /whole physical cores/);
});

test("validate: never the last core", () => {
  const r = validateReservation({ topology: I7, cpuset: "0-7", others: [] });
  assert.equal(r.ok, false);
  assert.match(r.errors.join(" "), /last physical core/);
  const r2 = validateReservation({ topology: I7, cpuset: "3,7", others: [{ serverId: "a", cpuset: "0-2,4-6" }] });
  assert.equal(r2.ok, false);
  assert.match(r2.errors.join(" "), /last physical core/);
  const r3 = validateReservation({ topology: I7, cpuset: "2,6", others: [{ serverId: "a", cpuset: "0-1,4-5" }], minSharedCores: 2 });
  assert.equal(r3.ok, false);
  assert.match(r3.errors.join(" "), /At least 2/);
});

test("validate: never overlaps another reservation", () => {
  const r = validateReservation({ topology: I7, cpuset: "2,6", others: [{ serverId: "a", cpuset: "0-2,4-6", label: "syntech-vps" }] });
  assert.equal(r.ok, false);
  assert.match(r.errors.join(" "), /already reserved \(syntech-vps\)/);
});

test("validate: unknown cpus, unparseable input and pve-only topology are refused", () => {
  assert.equal(validateReservation({ topology: I7, cpuset: "8,12", others: [] }).ok, false);
  assert.equal(validateReservation({ topology: I7, cpuset: "0;reboot", others: [] }).ok, false);
  const pve = validateReservation({ topology: { source: "pve", threadCount: 8, threads: [] }, cpuset: "0,4", others: [] });
  assert.equal(pve.ok, false);
  assert.match(pve.errors.join(" "), /topology/);
  assert.equal(validateReservation({ topology: null, cpuset: "0,4", others: [] }).ok, false);
});

test("validate: vCPU/thread mismatch is a warning, not an error", () => {
  const r = validateReservation({ topology: I7, cpuset: "0,4", others: [], vcpu: 6 });
  assert.equal(r.ok, true);
  assert.match(r.warnings.join(" "), /contend/);
});

const RES = [{ id: "r1", serverId: "syn", cpuset: "0-2,4-6", vmid: 667 }];

test("desired affinity: reserved VM gets its set, every other VM the shared pool, templates and unreserved nodes untouched", () => {
  assert.deepEqual(desiredAffinity({ vmid: 667, topology: I7, reservations: RES }), { cpuset: "0-2,4-6", reason: "reserved" });
  assert.deepEqual(desiredAffinity({ vmid: 700, topology: I7, reservations: RES }), { cpuset: "3,7", reason: "shared" });
  assert.deepEqual(desiredAffinity({ vmid: 9000, isTemplate: true, topology: I7, reservations: RES }), { cpuset: null, reason: "template" });
  assert.deepEqual(desiredAffinity({ vmid: 700, topology: I7, reservations: [] }), { cpuset: null, reason: "unmanaged" });
});

test("desired affinity: fails closed when the shared pool cannot be computed", () => {
  assert.throws(() => desiredAffinity({ vmid: 700, topology: null, reservations: RES }), /no shared pool/);
  assert.throws(() => desiredAffinity({ vmid: 667, topology: I7, reservations: [{ ...RES[0], cpuset: "bad" }] }), /unparseable/);
});

test("drift + sharing: a new VM running on all threads is drift AND a breach of the reservation", () => {
  const vms = [
    { vmid: 667, template: false, running: true, configAffinity: "0-2,4-6", threads: [{ tid: 1, cpus: "0-2,4-6" }] },
    { vmid: 700, template: false, running: true, configAffinity: null, threads: [{ tid: 2, cpus: "0-7" }] },
    { vmid: 701, template: false, running: false, configAffinity: "3,7", threads: [] },
    { vmid: 9000, template: true, running: false, configAffinity: null, threads: [] },
  ];
  const d667 = affinityDrift("0-2,4-6", vms[0]);
  assert.equal(d667.configOk && d667.badThreads.length === 0, true);
  const d700 = affinityDrift("3,7", vms[1]);
  assert.equal(d700.configOk, false);
  assert.equal(d700.badThreads.length, 1);
  assert.equal(affinityDrift("3,7", vms[2]).configOk, true);
  const s = findSharing(RES, vms, [0, 1, 2, 3, 4, 5, 6, 7]);
  assert.equal(s.length, 1);
  assert.deepEqual(s[0].offenders.map((o) => `${o.vmid}:${o.where}`), ["700:config", "700:live"]);
  // After the fix nobody but 667 can reach 0-2,4-6.
  const fixed = vms.map((v) => (v.vmid === 700 ? { ...v, configAffinity: "3,7", threads: [{ tid: 2, cpus: "3,7" }] } : v));
  assert.deepEqual(findSharing(RES, fixed, [0, 1, 2, 3, 4, 5, 6, 7]), []);
});
