import { test } from "node:test";
import assert from "node:assert/strict";
import { cpuVerdict, isRoomy, rankCandidates, parseCpuSchedMode, parseOvercommitRatio, type RankInput } from "../lib/cpu-placement";
import { nodeCpuFacts } from "../lib/node-capacity";
import type { CpuTopology } from "../lib/cpu-reservation";

const I7: CpuTopology = {
  source: "agent",
  threadCount: 8,
  threads: [0, 1, 2, 3, 4, 5, 6, 7].map((cpu) => ({ cpu, core: cpu % 4, socket: 0, siblings: `${cpu % 4},${(cpu % 4) + 4}` })),
};

test("settings parsing: unknown values fall back to the defaults, ratio is clamped", () => {
  assert.equal(parseCpuSchedMode("OFF"), "off");
  assert.equal(parseCpuSchedMode("guard"), "guard");
  assert.equal(parseCpuSchedMode("nonsense"), "score");
  assert.equal(parseOvercommitRatio("2.5"), 2.5);
  assert.equal(parseOvercommitRatio("0"), 4);
  assert.equal(parseOvercommitRatio("999"), 32);
});

test("node facts: node-6 with syntech-vps reserved has a 2-thread shared pool and excludes the reservation owner's vCPU", () => {
  const f = nodeCpuFacts({ id: "n6", cpuTopology: I7 }, [{ id: "syn", vcpu: 6 }, { id: "other", vcpu: 2 }], [{ serverId: "syn", cpuset: "0-2,4-6" }]);
  assert.equal(f.poolThreads, 2);
  assert.equal(f.committedVcpu, 2);
  assert.equal(f.hasReservations, true);
  const g = nodeCpuFacts({ id: "n4", cpuTopology: I7 }, [{ id: "a", vcpu: 41 }], []);
  assert.equal(g.poolThreads, 8);
  assert.equal(g.committedVcpu, 41);
  assert.equal(nodeCpuFacts({ id: "x", cpuTopology: null }, [], []).poolThreads, null);
});

test("guard: the shared pool refuses a VM that does not fit its budget; nodes without reservations never refuse on CPU", () => {
  const shared = { poolThreads: 2, committedVcpu: 6, hasReservations: true };
  assert.equal(cpuVerdict(shared, 2, 4, "score").refused, false); // 8 <= 8
  const over = cpuVerdict(shared, 3, 4, "score");
  assert.equal(over.refused, true);
  assert.match(over.reason!, /shared CPU pool full/);
  assert.equal(cpuVerdict(shared, 3, 4, "guard").refused, true);
  assert.equal(cpuVerdict(shared, 3, 4, "off").refused, false);
  assert.equal(cpuVerdict({ poolThreads: 8, committedVcpu: 400, hasReservations: false }, 16, 4, "score").refused, false);
  // Unknown pool on a reserved node fails closed; elsewhere it is neutral.
  assert.equal(cpuVerdict({ poolThreads: null, committedVcpu: 0, hasReservations: true }, 1, 4, "score").refused, true);
  assert.equal(cpuVerdict({ poolThreads: null, committedVcpu: 0, hasReservations: false }, 1, 4, "score").refused, false);
});

function cand(name: string, ramPct: number, freeRamMB: number, cpuPct: number | null, hasReservations = false): RankInput<string> {
  return { item: name, ramPct, freeRamMB, hasReservations, cpu: { projectedPct: cpuPct, budgetVcpu: null, refused: false, reason: null } };
}

test("score: picks the node whose busier dimension is lowest; off/guard keep the legacy most-free-RAM order", () => {
  const a = cand("ram-rich-cpu-hot", 40, 30000, 130);
  const b = cand("balanced", 60, 20000, 50);
  const c = cand("unknown-cpu", 70, 10000, null);
  assert.deepEqual(rankCandidates([a, b, c], "score").map((x) => x.item), ["balanced", "unknown-cpu", "ram-rich-cpu-hot"]);
  assert.deepEqual(rankCandidates([a, b, c], "guard").map((x) => x.item), ["ram-rich-cpu-hot", "balanced", "unknown-cpu"]);
  assert.deepEqual(rankCandidates([a, b, c], "off").map((x) => x.item), ["ram-rich-cpu-hot", "balanced", "unknown-cpu"]);
  // ties on the worst dimension → more free RAM wins
  assert.deepEqual(rankCandidates([cand("x", 50, 1, 50), cand("y", 50, 2, 40)], "score").map((x) => x.item), ["y", "x"]);
});

test("roomy: CPU makes only a reserved node non-roomy, so CPU overcommit alone never sells out a region", () => {
  assert.equal(isRoomy(cand("n4", 50, 1, 160, false), 90, "score"), true);
  assert.equal(isRoomy(cand("n6", 50, 1, 95, true), 90, "score"), false);
  assert.equal(isRoomy(cand("n6", 50, 1, 95, true), 90, "off"), true);
  assert.equal(isRoomy(cand("ram", 95, 1, 10, false), 90, "score"), false);
});
