import { test } from "node:test";
import assert from "node:assert/strict";
import { createRequire } from "node:module";
import { spawn, execFile as execFileCb } from "node:child_process";
import { promisify } from "node:util";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

/**
 * node-agent v5 CPU endpoints (node-agent/index.js). The system-touching
 * functions take injectable roots/exec, so everything that would run `qm` or
 * `taskset` is exercised against a FAKE /sys, /proc, qemu-server conf dir and a
 * recording exec — never a real VM. The HTTP part only sends requests that are
 * refused before any command runs (or target a vmid with no config here), plus
 * the read-only topology GET.
 */
const AGENT_PATH = path.resolve(__dirname, "../node-agent/index.js");
const agent = createRequire(__filename)(AGENT_PATH);
const execFile = promisify(execFileCb);

function fakeHost(): { root: string; sys: string; proc: string; conf: string; run: string } {
  const root = mkdtempSync(path.join(tmpdir(), "nxeon-cpu-fake-"));
  const sys = path.join(root, "sys");
  const cpuDir = path.join(sys, "devices/system/cpu");
  mkdirSync(cpuDir, { recursive: true });
  writeFileSync(path.join(cpuDir, "online"), "0-7\n");
  for (let c = 0; c < 8; c++) {
    const t = path.join(cpuDir, `cpu${c}`, "topology");
    mkdirSync(t, { recursive: true });
    writeFileSync(path.join(t, "core_id"), `${c % 4}\n`);
    writeFileSync(path.join(t, "physical_package_id"), "0\n");
    writeFileSync(path.join(t, "thread_siblings_list"), `${c % 4},${(c % 4) + 4}\n`);
  }
  const proc = path.join(root, "proc");
  mkdirSync(proc, { recursive: true });
  writeFileSync(path.join(proc, "cpuinfo"), "processor\t: 0\nmodel name\t: Intel(R) Core(TM) i7-7700K CPU @ 4.20GHz\n");
  const conf = path.join(root, "qemu-server");
  const run = path.join(root, "run");
  mkdirSync(conf);
  mkdirSync(run);
  return { root, sys, proc, conf, run };
}

function addVm(h: ReturnType<typeof fakeHost>, vmid: number, conf: string, live?: { pid: number; cpus: string[]; id?: number }) {
  writeFileSync(path.join(h.conf, `${vmid}.conf`), conf);
  if (live) {
    writeFileSync(path.join(h.run, `${vmid}.pid`), `${live.pid}\n`);
    mkdirSync(path.join(h.proc, String(live.pid), "task"), { recursive: true });
    writeFileSync(path.join(h.proc, String(live.pid), "cmdline"), ["/usr/bin/kvm", "-id", String(live.id ?? vmid), "-name", `vm${vmid}`].join("\0") + "\0");
    live.cpus.forEach((c, i) => {
      const td = path.join(h.proc, String(live.pid), "task", String(live.pid + i));
      mkdirSync(td, { recursive: true });
      writeFileSync(path.join(td, "status"), `Name:\tkvm\nCpus_allowed_list:\t${c}\n`);
    });
  }
}

test("agent: reads topology from /sys", () => {
  const h = fakeHost();
  try {
    const t = agent.readCpuTopology(h.sys, h.proc);
    assert.equal(t.threadCount, 8);
    assert.equal(t.online, "0-7");
    assert.deepEqual(t.threads[5], { cpu: 5, core: 1, socket: 0, siblings: "1,5" });
    assert.match(t.model, /7700K/);
  } finally {
    rmSync(h.root, { recursive: true, force: true });
  }
});

test("agent: conf parser honours [PENDING] and pending deletes, ignores snapshot sections", () => {
  assert.equal(agent.parseVmConf("affinity: 0-2,4-6\ncores: 6\n").affinity, "0-2,4-6");
  assert.equal(agent.parseVmConf("cores: 2\n[PENDING]\naffinity: 3,7\n").affinity, "3,7");
  assert.equal(agent.parseVmConf("affinity: 3,7\n[PENDING]\ndelete: affinity\n").affinity, null);
  assert.equal(agent.parseVmConf("cores: 2\n[snap1]\naffinity: 0-7\n").affinity, null);
  assert.equal(agent.parseVmConf("template: 1\n").template, true);
});

test("agent: lists every VM with config + live thread affinity, and never trusts a pidfile whose process is another vmid", () => {
  const h = fakeHost();
  try {
    addVm(h, 667, "affinity: 0-2,4-6\ncores: 6\n", { pid: 5000, cpus: ["0-2,4-6", "0-2,4-6"] });
    addVm(h, 700, "cores: 2\n", { pid: 6000, cpus: ["0-7"] });
    addVm(h, 701, "cores: 1\n", { pid: 7000, cpus: ["0-7"], id: 999 }); // stale pidfile → pid reused by another VM
    addVm(h, 9000, "template: 1\n");
    writeFileSync(path.join(h.conf, "notes.txt"), "ignore me");
    const vms = agent.readVmAffinities({ confDir: h.conf, runDir: h.run, procRoot: h.proc });
    assert.deepEqual(vms.map((v: any) => v.vmid), [667, 700, 701, 9000]);
    assert.deepEqual(vms[0], { vmid: 667, template: false, running: true, configAffinity: "0-2,4-6", threads: [{ tid: 5000, cpus: "0-2,4-6" }, { tid: 5001, cpus: "0-2,4-6" }] });
    assert.equal(vms[1].configAffinity, null);
    assert.equal(vms[2].running, false);
    assert.equal(vms[3].template, true);
  } finally {
    rmSync(h.root, { recursive: true, force: true });
  }
});

test("agent: request validation is strict (injection-safe)", () => {
  const online = [0, 1, 2, 3, 4, 5, 6, 7];
  assert.deepEqual(agent.validateAffinityRequest({ vmid: 700, cpuset: "7,3" }, online), { vmid: 700, cpuset: "3,7" });
  assert.deepEqual(agent.validateAffinityRequest({ vmid: 700, cpuset: null }, online), { vmid: 700, cpuset: null });
  const bad: unknown[] = [
    null, [], "x", {},
    { vmid: "700", cpuset: "3,7" }, { vmid: 700.5, cpuset: "3,7" }, { vmid: 99, cpuset: "3,7" }, { vmid: 1e10, cpuset: "3,7" },
    { vmid: 700, cpuset: "3,7; reboot" }, { vmid: 700, cpuset: "$(id)" }, { vmid: 700, cpuset: "--delete" }, { vmid: 700, cpuset: ["3"] },
    { vmid: 700, cpuset: "" }, { vmid: 700, cpuset: "8" }, { vmid: 700, cpuset: 3 }, { vmid: 700 },
  ];
  for (const b of bad) assert.ok(agent.validateAffinityRequest(b, online).error, `should refuse ${JSON.stringify(b)}`);
});

test("agent: set runs exactly `qm set <vmid> --affinity <set>` + `taskset -a -p -c <set> <pid>` as argv, then re-reads", async () => {
  const h = fakeHost();
  try {
    addVm(h, 700, "cores: 2\n", { pid: 6000, cpus: ["0-7", "0-7"] });
    const calls: string[][] = [];
    const exec = async (cmd: string, args: string[]) => {
      calls.push([cmd, ...args]);
      if (cmd === "qm") writeFileSync(path.join(h.conf, "700.conf"), "cores: 2\naffinity: 3,7\n");
      if (cmd === "taskset") for (const tid of ["6000", "6001"]) writeFileSync(path.join(h.proc, "6000", "task", tid, "status"), "Cpus_allowed_list:\t3,7\n");
      return "";
    };
    const out = await agent.setVmAffinity(700, "3,7", { confDir: h.conf, runDir: h.run, procRoot: h.proc, sysRoot: h.sys, exec });
    assert.deepEqual(calls, [["qm", "set", "700", "--affinity", "3,7"], ["taskset", "-a", "-p", "-c", "3,7", "6000"]]);
    assert.equal(out.configAffinity, "3,7");
    assert.ok(out.threads.every((t: any) => t.cpus === "3,7"));
    // Idempotent: already right → no commands.
    calls.length = 0;
    await agent.setVmAffinity(700, "3,7", { confDir: h.conf, runDir: h.run, procRoot: h.proc, sysRoot: h.sys, exec });
    assert.deepEqual(calls, []);
    // Clear → --delete affinity and widen live threads to every online cpu.
    await agent.setVmAffinity(700, null, { confDir: h.conf, runDir: h.run, procRoot: h.proc, sysRoot: h.sys, exec, onlineCpus: [0, 1, 2, 3, 4, 5, 6, 7] });
    assert.deepEqual(calls, [["qm", "set", "700", "--delete", "affinity"], ["taskset", "-a", "-p", "-c", "0-7", "6000"]]);
  } finally {
    rmSync(h.root, { recursive: true, force: true });
  }
});

test("agent: set refuses templates and VMs without a config on this node, and never tasksets a mismatched pid", async () => {
  const h = fakeHost();
  try {
    addVm(h, 9000, "template: 1\n");
    addVm(h, 701, "cores: 1\n", { pid: 7000, cpus: ["0-7"], id: 999 });
    const calls: string[][] = [];
    const exec = async (cmd: string, args: string[]) => { calls.push([cmd, ...args]); return ""; };
    const sys = { confDir: h.conf, runDir: h.run, procRoot: h.proc, sysRoot: h.sys, exec };
    await assert.rejects(agent.setVmAffinity(9000, "3,7", sys), /template/);
    await assert.rejects(agent.setVmAffinity(123456, "3,7", sys), /no config/);
    await agent.setVmAffinity(701, "3,7", sys);
    assert.deepEqual(calls, [["qm", "set", "701", "--affinity", "3,7"]]); // config only — pid 7000 is not VM 701
  } finally {
    rmSync(h.root, { recursive: true, force: true });
  }
});

// ---- HTTP (real agent process; only refused / read-only requests) ----------
const TOKEN = "test-token-" + Math.random().toString(36).slice(2) + "-cpu";
const PORT = 18944;

test("agent HTTP: v5 health, read-only topology, and every invalid affinity request is refused before any command", async () => {
  const dir = mkdtempSync(path.join(tmpdir(), "nxeon-agent-cpu-"));
  const key = path.join(dir, "k.pem");
  const cert = path.join(dir, "c.pem");
  await execFile("openssl", ["req", "-x509", "-newkey", "rsa:2048", "-nodes", "-keyout", key, "-out", cert, "-days", "1", "-subj", "/CN=t"]);
  const proc = spawn(process.execPath, [AGENT_PATH], {
    env: { ...process.env, NXEON_AGENT_PORT: String(PORT), NXEON_AGENT_TOKEN: TOKEN, NXEON_AGENT_TLS_KEY: key, NXEON_AGENT_TLS_CERT: cert },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let out = "";
  proc.stdout?.on("data", (d) => (out += d));
  proc.stderr?.on("data", (d) => (out += d));
  const prevTls = process.env.NODE_TLS_REJECT_UNAUTHORIZED;
  process.env.NODE_TLS_REJECT_UNAUTHORIZED = "0";
  try {
    const deadline = Date.now() + 5000;
    while (!out.includes("listening") && Date.now() < deadline) await new Promise((r) => setTimeout(r, 50));
    assert.ok(out.includes("listening"), out);
    const call = async (method: string, p: string, body?: unknown, token = TOKEN) => {
      const res = await fetch(`https://127.0.0.1:${PORT}${p}`, { method, headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" }, body: body === undefined ? undefined : typeof body === "string" ? body : JSON.stringify(body) });
      return { status: res.status, json: await res.json().catch(() => null) };
    };
    const health = await call("GET", "/v1/health");
    assert.equal(health.json.version, 5);
    assert.ok(health.json.features.includes("cpu-affinity"));
    assert.equal((await call("GET", "/v1/cpu/topology", undefined, "wrong-token-xxxxxxxxxxxxxxxx")).status, 401);
    assert.equal((await call("POST", "/v1/vm/affinity", { vmid: 700, cpuset: "3" }, "wrong-token-xxxxxxxxxxxxxxxx")).status, 401);
    const topo = await call("GET", "/v1/cpu/topology");
    assert.equal(topo.status, 200);
    assert.ok(topo.json.threadCount >= 1);
    assert.equal((await call("GET", "/v1/cpu/affinity?vmid=12;rm")).status, 400);
    for (const body of ['{"vmid":', { vmid: "700", cpuset: "0" }, { vmid: 700, cpuset: "0;reboot" }, { vmid: 700, cpuset: "99999" }, { vmid: 700, cpuset: [0] }, { vmid: 42, cpuset: "0" }]) {
      const r = await call("POST", "/v1/vm/affinity", body);
      assert.equal(r.status, 400, JSON.stringify(body));
    }
    // Valid shape, but no such VM on this host → 404, nothing executed.
    assert.ok(!existsSync("/etc/pve/qemu-server/999999998.conf"));
    assert.equal((await call("POST", "/v1/vm/affinity", { vmid: 999999998, cpuset: "0" })).status, 404);
  } finally {
    if (prevTls === undefined) delete process.env.NODE_TLS_REJECT_UNAUTHORIZED;
    else process.env.NODE_TLS_REJECT_UNAUTHORIZED = prevTls;
    proc.kill();
    rmSync(dir, { recursive: true, force: true });
  }
});
