import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";

/**
 * SOURCE test: every path that creates or recreates a VM's config must confine
 * it (ensureVmAffinityBeforeStart) BEFORE it issues the Proxmox start — on a
 * node with CPU reservations a VM must never run, even briefly, on another
 * customer's dedicated cores. A new VM-creating path that forgets the step
 * fails here.
 */
const read = (p: string) => readFileSync(path.resolve(__dirname, "..", p), "utf8");

/** Body of `async function <name>(` up to the next top-level function. */
function fnBody(src: string, header: RegExp): string {
  const m = header.exec(src);
  assert.ok(m, `function ${header} not found`);
  const rest = src.slice(m.index + m[0].length);
  const next = /\n(?:export )?(?:async )?function \w+\(/.exec(rest);
  return rest.slice(0, next ? next.index : undefined);
}

function assertEnsureBeforeEveryStart(body: string, what: string) {
  const starts = [...body.matchAll(/qemu\/\$\{[^}]+\}\/status\/start`/g)].map((m) => m.index!);
  assert.ok(starts.length > 0, `${what}: no start call found (test out of date?)`);
  const ensures = [...body.matchAll(/ensureVmAffinityBeforeStart\(/g)].map((m) => m.index!);
  for (const s of starts) assert.ok(ensures.some((e) => e < s), `${what}: a status/start at offset ${s} has no ensureVmAffinityBeforeStart before it`);
}

const worker = read("worker/index.ts");

test("provision (also used by REINSTALL) confines the VM before its first start", () => {
  assertEnsureBeforeEveryStart(fnBody(worker, /async function provision\(job: Job\) \{/), "provision");
  assert.match(fnBody(worker, /async function reinstall\(job: Job\) \{/), /await provision\(job\)/);
});

test("resize re-asserts affinity before the cold start", () => {
  assertEnsureBeforeEveryStart(fnBody(worker, /async function resize\(job: Job\) \{/), "resize");
});

test("snapshot rollback (restores the snapshot's config) re-asserts affinity before start", () => {
  assertEnsureBeforeEveryStart(fnBody(worker, /async function snapshotOp\(job: Job, op: [^)]*\) \{/), "snapshotOp");
});

test("backup restore (qmrestore replaces the config) re-asserts affinity before start", () => {
  const restore = read("worker/restore.ts");
  assertEnsureBeforeEveryStart(restore, "restore");
});

test("VM move: the hypervisor start adapter (target start + rollback start) confines first, and affinity is never carried", () => {
  const mv = read("worker/vm-move.ts");
  const startFn = /async start\(vmid\) \{([\s\S]*?)\n    \},/.exec(mv);
  assert.ok(startFn, "start adapter not found");
  assert.ok(startFn[1].indexOf("ensureVmAffinityBeforeStart(") >= 0 && startFn[1].indexOf("ensureVmAffinityBeforeStart(") < startFn[1].indexOf("/status/start"));
  assert.match(mv, /hypervisorFor\(srcConn, source\.name, source\.id\)/);
  assert.match(mv, /hypervisorFor\(tgtConn, target\.name, target\.id\)/);
  const plan = read("lib/vm-move/plan.ts");
  const carried = /export const CARRIED_CONFIG_KEYS = \[([\s\S]*?)\]/.exec(plan)![1];
  assert.doesNotMatch(carried, /"affinity"/);
});

test("the job handler and the enforcement sweep are registered", () => {
  assert.match(worker, /CPU_AFFINITY: cpuAffinityJob/);
  assert.match(worker, /add\("cpu-affinity", m, cpuAffinitySweep/);
});

test("the web app never sets affinity itself (only enqueues CPU_AFFINITY jobs)", () => {
  const actions = read("lib/actions-cpu-reservation.ts");
  assert.doesNotMatch(actions, /node-agent|agentSetVmAffinity|qm set|execFile/);
  assert.match(actions, /type: "CPU_AFFINITY"/);
});
EOF
